// SPDX-License-Identifier: Apache-2.0
//! Parent/child and supersession conformance — SAS §20, §21.
//!
//! OW-WAR-0043 OBL-004 asks for §91.4 test 24 and §91.5 tests 30–35 to be
//! planted. Four of those claims already had rules in `openwarrant_core`
//! (`lifecycle::needs_adr`, `Currency::remains_available`,
//! `Supersession::validate`) and none of them was reachable from `war check`,
//! so nothing could be planted against them — a rule the binary never consults
//! is exactly the "declared but never executed" state this fleet keeps finding.
//! This module is the wiring, plus the three §20 rules that did not exist.
//!
//! | test | claim | rule |
//! |---|---|---|
//! | 30 | parent source unchanged when child state changes | `relations.parent-source` |
//! | 31 | parent generated view lists child | `relations.child-listed` |
//! | 32 | child cannot silently replace parent rationale | `relations.parent-source` |
//! | 33 | superseding WAR makes old currency `superseded` | `relations.currency`, derived (OW-ADR-0022) |
//! | 34 | superseded WAR remains exportable | `relations.retired-available` |
//! | 35 | adopted unresolved children are explicit | `relations.adoption` |
//!
//! Test 24 — "a local choice inside autonomy does not require a new ADR" — is a
//! POSITIVE claim and is checked in `crate::check` where amendments are read,
//! because it is a statement about what must be ACCEPTED rather than rejected.

use std::collections::BTreeMap;

use openwarrant_core::ValidatedManifest;

use crate::diagnostic::{Diagnostic, Report};

/// One Warrant as this module needs to see it.
pub struct Related<'a> {
    pub alias: String,
    pub manifest: &'a ValidatedManifest,
    pub manifest_file: String,
    /// The committed generated view, if one is on disk.
    pub generated_view: Option<String>,
    /// The concatenated bytes of every authored atom.
    pub atom_source: String,
}

/// §20.4 — the parent's generated view SHALL list child WARs and their states.
///
/// A stale view is the realistic failure: a child is added, nobody recompiles,
/// and the parent's Relations section silently describes a smaller family than
/// exists. `generated.drift` does not name that — it reports that SOMETHING
/// differs from a fresh compile, which is true of any edit. This names the
/// missing child, which is what a reader needs.
fn child_listed(corpus: &[Related<'_>], report: &mut Report) {
    let by_uuid: BTreeMap<&str, &Related<'_>> = corpus
        .iter()
        .map(|r| (r.manifest.raw.uuid.as_str(), r))
        .collect();

    let mut children_of: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for child in corpus {
        for parent in &child.manifest.raw.parents {
            let uuid = parent.r#ref.trim_start_matches("war://");
            children_of.entry(uuid).or_default().push(&child.alias);
        }
    }

    for (parent_uuid, children) in &children_of {
        let Some(parent) = by_uuid.get(parent_uuid) else {
            // An external parent is not this repository's to render.
            continue;
        };
        let Some(view) = &parent.generated_view else {
            report.push(Diagnostic::unknown(
                "relations.child-listed",
                parent.manifest_file.clone(),
                format!(
                    "{}: has {} child WAR(s) but no generated view is committed, so §20.4's \
                     child list cannot be checked. Run `war compile`.",
                    parent.alias,
                    children.len()
                ),
            ));
            continue;
        };
        // Look ONLY inside the generated `### Children` section.
        //
        // The first version of this rule searched the whole view, and passed for
        // three of OW-WAR-0001's four children — because its atoms happen to say
        // "Those are OW-WAR-0002 through OW-WAR-0004" in narrative prose. A rule
        // satisfied by a Warrant being MENTIONED is fail-open: it reports §20.4
        // as met by a document that never projected a child list at all.
        let section = view
            .split("\n### ")
            .find(|s| s.starts_with("Children\n"))
            .unwrap_or("");
        let missing: Vec<&str> = children
            .iter()
            .filter(|child| !section.contains(**child))
            .copied()
            .collect();
        if missing.is_empty() {
            report.push(Diagnostic::pass(
                "relations.child-listed",
                format!(
                    "{}: generated view lists all {} child WAR(s)",
                    parent.alias,
                    children.len()
                ),
            ));
        } else {
            report.push(Diagnostic::error(
                "relations.child-listed",
                parent.manifest_file.clone(),
                format!(
                    "{}: child WAR(s) {} are not listed in the parent's generated view. \
                     §20.4: the parent's generated Relations section SHALL list child WARs \
                     and their current states. A child that exists but is not projected \
                     leaves the parent describing a smaller family than it has.",
                    parent.alias,
                    missing.join(", ")
                ),
            ));
        }
    }
}

/// §20.3 and §20.4 — a child's state belongs in the parent's GENERATED view,
/// never in the parent's authored source.
///
/// §20.4 is explicit that the child list "is a bound/generated projection, not
/// an edit to the parent's original contract", and §20.3 forbids a child
/// outcome becoming the parent's supposed original rationale. Both fail the same
/// way in practice: someone writes a child's status into a parent atom, and the
/// parent's authored basis now moves whenever the child does.
fn parent_source(corpus: &[Related<'_>], report: &mut Report) {
    let mut children_of: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for child in corpus {
        for parent in &child.manifest.raw.parents {
            children_of
                .entry(parent.r#ref.trim_start_matches("war://"))
                .or_default()
                .push(&child.alias);
        }
    }
    // A child's ALIAS beside a state word in a parent's authored atom.
    const STATE_WORDS: [&str; 6] = [
        "resolved",
        "unresolved",
        "in progress",
        "superseded",
        "blocked",
        "complete",
    ];

    for parent in corpus {
        let Some(children) = children_of.get(parent.manifest.raw.uuid.as_str()) else {
            continue;
        };
        let mut offences = vec![];
        for line in parent.atom_source.lines() {
            let lower = line.to_lowercase();
            if !STATE_WORDS.iter().any(|w| lower.contains(w)) {
                continue;
            }
            for child in children {
                if line.contains(*child) {
                    offences.push(format!("{child} in {:?}", line.trim()));
                }
            }
        }
        if offences.is_empty() {
            report.push(Diagnostic::pass(
                "relations.parent-source",
                format!(
                    "{}: authored atoms carry no child state; §20.4's list stays generated",
                    parent.alias
                ),
            ));
        } else {
            report.push(Diagnostic::error(
                "relations.parent-source",
                parent.manifest_file.clone(),
                format!(
                    "{}: a child's state is written into the parent's AUTHORED source — {}. \
                     §20.4: the child list is a bound/generated projection, not an edit to \
                     the parent's original contract. §20.3: a child outcome SHALL NOT become \
                     the supposed original rationale of the parent.",
                    parent.alias,
                    offences.join("; ")
                ),
            ));
        }
    }
}

/// A Warrant's currency, DERIVED from the relations around it (OW-ADR-0022).
///
/// §21.2 says the replaced Warrant's currency *becomes* superseded and that
/// the replaced Warrant stays immutable. Both at once are only possible if
/// currency is a fact about the SUCCESSOR's relation, computed here, and never
/// a field edited into the predecessor: OW-WAR-0073 was marked
/// `currency = "superseded"` and its signed contract digest moved, because
/// the manifest's bytes are in the preimage.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
#[serde(tag = "currency", rename_all = "snake_case")]
pub enum Derived {
    Current,
    /// An authorized Warrant declares `supersedes` → this one.
    Superseded {
        by: String,
    },
    /// The resolution standing says annulled.
    Annulled,
    /// Only a legacy bare `currency = "deprecated"`, tolerated and reported.
    /// A successor's `deprecates` relation would be the relation form; the
    /// manifest schema has no such field and is frozen under OW-WAR-0113.
    Deprecated,
}

impl Derived {
    #[must_use]
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Current => "current",
            Self::Superseded { .. } => "superseded",
            Self::Annulled => "annulled",
            Self::Deprecated => "deprecated",
        }
    }

    #[must_use]
    pub const fn is_current(&self) -> bool {
        matches!(self, Self::Current)
    }

    /// §21.4's retired states: still available, not for new execution.
    #[must_use]
    pub const fn retired(&self) -> bool {
        !self.is_current()
    }
}

impl std::fmt::Display for Derived {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// One Warrant as the derivation needs it: identity, its outgoing
/// `supersedes`, whether its contract is authorized, whether its resolution
/// is annulled, and the legacy field it may still carry.
#[derive(Debug, Clone)]
pub struct CurrencyInput {
    pub alias: String,
    pub uuid: String,
    pub supersedes: Vec<String>,
    pub authorized: bool,
    pub annulled: bool,
    pub written: Option<String>,
}

/// The derivation over a whole corpus, and what it found on the way.
#[derive(Debug, Clone, Default)]
pub struct Currencies {
    by_alias: BTreeMap<String, Derived>,
    /// `(successor, predecessor)` declared by a successor not yet authorized:
    /// the relation is on record and not in force.
    pub pending: Vec<(String, String)>,
    /// `(successor, ref)` whose target is not in this corpus.
    pub external: Vec<(String, String)>,
    /// Each `supersedes` cycle once, as aliases starting from the least.
    pub cycles: Vec<Vec<String>>,
}

impl Currencies {
    /// The derived currency of `alias`; `Current` for an alias the corpus
    /// did not contain, which is the answer the relations give it.
    #[must_use]
    pub fn of(&self, alias: &str) -> Derived {
        self.by_alias
            .get(alias)
            .cloned()
            .unwrap_or(Derived::Current)
    }

    pub fn iter(&self) -> impl Iterator<Item = (&str, &Derived)> {
        self.by_alias.iter().map(|(a, d)| (a.as_str(), d))
    }

    /// The pure derivation. Separated from I/O so it is testable on
    /// synthetic corpora and so every reader calls the one computation.
    #[must_use]
    pub fn derive(inputs: &[CurrencyInput]) -> Self {
        let alias_of: BTreeMap<&str, &str> = inputs
            .iter()
            .map(|i| (i.uuid.as_str(), i.alias.as_str()))
            .collect();
        let mut out = Self::default();
        let mut superseded_by: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
        for i in inputs {
            for r in &i.supersedes {
                let uuid = r.trim_start_matches("war://");
                let Some(old) = alias_of.get(uuid) else {
                    out.external.push((i.alias.clone(), r.clone()));
                    continue;
                };
                if i.authorized {
                    superseded_by.entry(old).or_default().push(&i.alias);
                } else {
                    out.pending.push((i.alias.clone(), (*old).to_owned()));
                }
            }
        }
        for i in inputs {
            let d = if i.annulled {
                Derived::Annulled
            } else if let Some(by) = superseded_by.get(i.alias.as_str()) {
                let mut by = by.clone();
                by.sort_unstable();
                Derived::Superseded { by: by.join(", ") }
            } else if i.written.as_deref() == Some("deprecated") {
                Derived::Deprecated
            } else {
                Derived::Current
            };
            out.by_alias.insert(i.alias.clone(), d);
        }
        out.cycles = cycles(inputs, &alias_of);
        out
    }
}

/// Every `supersedes` cycle, each reported once from its least alias. A
/// cycle has no current subject at either end, so no currency derived over
/// it means anything (R-001).
fn cycles(inputs: &[CurrencyInput], alias_of: &BTreeMap<&str, &str>) -> Vec<Vec<String>> {
    let edges: BTreeMap<&str, Vec<&str>> = inputs
        .iter()
        .map(|i| {
            let mut to: Vec<&str> = i
                .supersedes
                .iter()
                .filter_map(|r| alias_of.get(r.trim_start_matches("war://")).copied())
                .collect();
            to.sort_unstable();
            (i.alias.as_str(), to)
        })
        .collect();
    let mut found: std::collections::BTreeSet<Vec<String>> = std::collections::BTreeSet::new();
    // Small graphs, and supersession is sparse: a DFS from every node that
    // records the path is enough and keeps the order deterministic.
    fn walk<'a>(
        node: &'a str,
        edges: &BTreeMap<&'a str, Vec<&'a str>>,
        path: &mut Vec<&'a str>,
        found: &mut std::collections::BTreeSet<Vec<String>>,
    ) {
        if let Some(pos) = path.iter().position(|p| *p == node) {
            let cycle = &path[pos..];
            let least = cycle
                .iter()
                .enumerate()
                .min_by_key(|(_, a)| **a)
                .map_or(0, |(i, _)| i);
            let mut rotated: Vec<String> = cycle[least..]
                .iter()
                .chain(cycle[..least].iter())
                .map(|a| (*a).to_owned())
                .collect();
            rotated.push(rotated[0].clone());
            found.insert(rotated);
            return;
        }
        path.push(node);
        for next in edges.get(node).map(Vec::as_slice).unwrap_or(&[]) {
            walk(next, edges, path, found);
        }
        path.pop();
    }
    for start in edges.keys() {
        if edges.get(start).is_some_and(|e| !e.is_empty()) {
            walk(start, &edges, &mut Vec::new(), &mut found);
        }
    }
    found.into_iter().collect()
}

/// The derivation over loaded Warrants: reads each one's `authorization.toml`
/// and `resolution.toml` beside its manifest. The one place currency is
/// computed; `check`, `ownership`, `compile` and both projections read it.
#[must_use]
pub fn currencies(corpus: &[crate::repo::Loaded]) -> Currencies {
    let inputs: Vec<CurrencyInput> = corpus
        .iter()
        .filter_map(|one| {
            let v = one.validated.as_ref()?;
            let read = |name: &str| std::fs::read_to_string(one.dir.join(name)).ok();
            let authorized = !v.raw.supersedes.is_empty()
                && read("authorization.toml")
                    .and_then(|t| toml::from_str::<crate::authorize::AuthorizationRecord>(&t).ok())
                    .is_some_and(|r| {
                        r.revision.state == openwarrant_core::RevisionState::Authorized
                    });
            let annulled = read("resolution.toml")
                .and_then(|t| toml::from_str::<crate::resolution_cmd::ResolutionRecord>(&t).ok())
                .is_some_and(|r| {
                    r.resolution.standing == openwarrant_core::ResolutionStanding::Annulled
                });
            Some(CurrencyInput {
                alias: v.alias.to_string(),
                uuid: v.raw.uuid.clone(),
                supersedes: v.raw.supersedes.iter().map(|s| s.r#ref.clone()).collect(),
                authorized,
                annulled,
                written: v.raw.currency.clone(),
            })
        })
        .collect();
    Currencies::derive(&inputs)
}

/// §21.2 — the replaced WAR's canonical currency becomes `superseded`, by
/// relation. Three rules, one derivation:
///
/// - `relations.currency` — PASS on each supersession in force, naming the
///   successor; a declared one awaiting authorization is on record and not
///   yet in force.
/// - `relations.currency-authored` — a manifest that WRITES `superseded` or
///   `annulled` is refused: those are facts about a successor or a
///   resolution, and the predecessor's bytes are under a signature. A bare
///   `deprecated` is a legacy form, tolerated and reported.
/// - `relations.currency-cycle` — a `supersedes` cycle is refused.
fn currency(corpus: &[Related<'_>], currencies: &Currencies, report: &mut Report) {
    let file_of: BTreeMap<&str, &str> = corpus
        .iter()
        .map(|r| (r.alias.as_str(), r.manifest_file.as_str()))
        .collect();
    for (alias, d) in currencies.iter() {
        if let Derived::Superseded { by } = d {
            report.push(Diagnostic::pass(
                "relations.currency",
                format!(
                    "{alias}: superseded, derived from {by}'s authorized `supersedes`; \
                      nothing is written in {alias}'s manifest"
                ),
            ));
        }
    }
    for (successor, old) in &currencies.pending {
        report.push(Diagnostic::pass(
            "relations.currency",
            format!(
                "{successor}: declares `supersedes` → {old}, not in force until {successor} \
                  is authorized; {old} reads current"
            ),
        ));
    }
    for (successor, r) in &currencies.external {
        report.push(Diagnostic::unknown(
            "relations.currency",
            file_of
                .get(successor.as_str())
                .copied()
                .unwrap_or_default()
                .to_owned(),
            format!(
                "{successor}: supersedes {r} which is not in this repository, so its §21.2 \
                  currency cannot be derived here"
            ),
        ));
    }
    for w in corpus {
        let Some(written) = w.manifest.raw.currency.as_deref() else {
            continue;
        };
        match written {
            "superseded" | "annulled" => report.push(Diagnostic::error(
                "relations.currency-authored",
                w.manifest_file.clone(),
                format!(
                    "{}: the manifest writes `currency = {written:?}`. Currency is derived \
                      from relations (OW-ADR-0022): superseded when an authorized Warrant \
                      declares `supersedes` → this one, annulled from the resolution \
                      standing. Writing it into this manifest moves a signed contract \
                      digest (OW-WAR-0073). Remove the field; the successor's relation \
                      already says it",
                    w.alias
                ),
            )),
            "deprecated" | "current" => report.push(Diagnostic::warn(
                "relations.currency-authored",
                w.manifest_file.clone(),
                format!(
                    "{}: the manifest writes `currency = {written:?}` — a legacy field, \
                      tolerated. Currency is derived from relations (OW-ADR-0022); this \
                      reads {}",
                    w.alias,
                    currencies.of(&w.alias)
                ),
            )),
            other => report.push(Diagnostic::error(
                "relations.currency-authored",
                w.manifest_file.clone(),
                format!(
                    "{}: `currency = {other:?}` is not a §21 currency, and currency is not \
                      written at all: it is derived from relations (OW-ADR-0022)",
                    w.alias
                ),
            )),
        }
    }
    for cycle in &currencies.cycles {
        report.push(Diagnostic::error(
            "relations.currency-cycle",
            file_of
                .get(cycle[0].as_str())
                .copied()
                .unwrap_or_default()
                .to_owned(),
            format!(
                "`supersedes` cycle: {}. Each Warrant in it is replaced by another in it, \
                  so none is current and no currency derived over it means anything. Break \
                  the cycle: supersession runs one way",
                cycle.join(" → ")
            ),
        ));
    }
}

/// §21.4 — superseded and deprecated WARs SHALL remain available.
///
/// "Available" is checked as: the manifest still loads and its atoms are still
/// on disk. A retired Warrant whose atoms were deleted is the deletion §21.4
/// forbids, whatever the manifest still says. Retired is the DERIVED currency.
fn retired_available(corpus: &[Related<'_>], currencies: &Currencies, report: &mut Report) {
    for warrant in corpus {
        let currency = currencies.of(&warrant.alias);
        if !currency.retired() {
            continue;
        }
        if warrant.atom_source.trim().is_empty() {
            report.push(Diagnostic::error(
                "relations.retired-available",
                warrant.manifest_file.clone(),
                format!(
                    "{}: currency is {currency} but its authored atoms are empty or missing. \
                     §21.4: superseded and deprecated WARs SHALL remain available for audit \
                     and relation traversal — retiring a Warrant is not deleting it.",
                    warrant.alias
                ),
            ));
        } else {
            report.push(Diagnostic::pass(
                "relations.retired-available",
                format!(
                    "{}: currency {currency} and its source remains available (§21.4)",
                    warrant.alias
                ),
            ));
        }
    }
}

/// §21.5 — a superseding WAR SHALL explicitly identify what it adopts.
///
/// The check is deliberately about EXPLICITNESS, not about the adoption being
/// correct. "Nothing is silently carried forward" is a statement about the
/// record saying what happened, and an empty `adopts` beside a superseded
/// Warrant that had children is silence.
fn adoption(corpus: &[Related<'_>], report: &mut Report) {
    let mut children_of: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for child in corpus {
        for parent in &child.manifest.raw.parents {
            children_of
                .entry(parent.r#ref.trim_start_matches("war://"))
                .or_default()
                .push(&child.alias);
        }
    }

    for replacement in corpus {
        for superseded in &replacement.manifest.raw.supersedes {
            let uuid = superseded.r#ref.trim_start_matches("war://");
            let inherited = children_of.get(uuid).map_or(0, Vec::len);
            if inherited == 0 {
                continue;
            }
            if superseded.adopts.is_empty() {
                report.push(Diagnostic::error(
                    "relations.adoption",
                    replacement.manifest_file.clone(),
                    format!(
                        "{}: supersedes {} which has {inherited} child WAR(s), and adopts \
                         nothing explicitly. §21.5: a superseding WAR SHALL explicitly \
                         identify which unresolved child WARs, deliverables, evidence or \
                         obligations it adopts — nothing is silently carried forward. \
                         Adopting none is a legitimate answer, but it has to be stated.",
                        replacement.alias, superseded.r#ref
                    ),
                ));
            } else {
                report.push(Diagnostic::pass(
                    "relations.adoption",
                    format!(
                        "{}: names {} adoption(s) from {} (§21.5)",
                        replacement.alias,
                        superseded.adopts.len(),
                        superseded.r#ref
                    ),
                ));
            }
        }
    }
}

/// Run every §20/§21 relation rule.
pub fn check(corpus: &[Related<'_>], currencies: &Currencies, report: &mut Report) {
    child_listed(corpus, report);
    parent_source(corpus, report);
    currency(corpus, currencies, report);
    retired_available(corpus, currencies, report);
    adoption(corpus, report);
}

#[cfg(test)]
mod tests {
    use super::*;

    fn w(alias: &str, supersedes: &[&str], authorized: bool) -> CurrencyInput {
        CurrencyInput {
            alias: alias.into(),
            uuid: format!("u-{alias}"),
            supersedes: supersedes.iter().map(|a| format!("war://u-{a}")).collect(),
            authorized,
            annulled: false,
            written: None,
        }
    }

    #[test]
    fn an_authorized_successor_supersedes_and_a_draft_does_not() {
        let c = Currencies::derive(&[w("A", &[], false), w("B", &["A"], true)]);
        assert_eq!(c.of("A"), Derived::Superseded { by: "B".into() });
        assert_eq!(c.of("B"), Derived::Current);
        let c = Currencies::derive(&[w("A", &[], false), w("B", &["A"], false)]);
        assert_eq!(c.of("A"), Derived::Current);
        assert_eq!(c.pending, vec![("B".to_owned(), "A".to_owned())]);
    }

    #[test]
    fn a_written_field_does_not_make_a_warrant_superseded() {
        let mut a = w("A", &[], false);
        a.written = Some("superseded".into());
        assert_eq!(Currencies::derive(&[a]).of("A"), Derived::Current);
    }

    #[test]
    fn annulled_comes_from_the_resolution_and_deprecated_from_the_legacy_field() {
        let mut a = w("A", &[], false);
        a.annulled = true;
        let mut b = w("B", &[], false);
        b.written = Some("deprecated".into());
        let c = Currencies::derive(&[a, b]);
        assert_eq!(c.of("A"), Derived::Annulled);
        assert_eq!(c.of("B"), Derived::Deprecated);
    }

    #[test]
    fn a_cycle_is_found_once() {
        let c = Currencies::derive(&[
            w("A", &["C"], true),
            w("B", &["A"], true),
            w("C", &["B"], true),
            w("D", &[], true),
        ]);
        assert_eq!(c.cycles.len(), 1);
        assert_eq!(c.cycles[0].first(), Some(&"A".to_owned()));
        assert_eq!(c.cycles[0].len(), 4);
        let none = Currencies::derive(&[w("A", &[], true), w("B", &["A"], true)]);
        assert!(none.cycles.is_empty());
    }
}

// SPDX-License-Identifier: Apache-2.0
//! Who governs a delivered path (OW-ADR-0021, SAS §37.5).
//!
//! A pin used to be forever: a resolved Warrant's `deliverables.toml` bound
//! each file's digest, and every later edit — however legitimate, under
//! however new a Warrant — needed a human-signed correction from every
//! Warrant that once delivered it. Under this module a path is governed by
//! the most recently AUTHORIZED Warrant whose recorded declaration set names
//! it. Earlier pins are historical: still recorded, still verifiable at their
//! own resolution, and not drift.
//!
//! Two facts shape the record this reads. Deliverables are not inside the
//! contract digest, so `deliverables.toml` can move after signing — which is
//! why the set is copied into `authorization.toml` at ingest, under the
//! attestation, and read from there and never from the manifest. And
//! `war pins --refresh` rewrites content digests during ordinary work, so the
//! thing an authorizer grants is the set of `(id, target_ref)` PAIRS, not
//! bytes. [`set_digest`] is the digest of exactly that.
//!
//! An authorization recorded before OW-ADR-0021 carries no set and owns
//! nothing. That is fail-closed and deliberate: nobody gains ownership without
//! a fresh human signature over a request that lists the paths.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::repo::{RepoError, Repository};

/// One `(id, target_ref)` pair as the authorizer saw it. Lives here rather
/// than in `authorize.rs` so `pins`, `correct` and `check` can name it without
/// importing the whole authorization surface.
#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct OwnedDeliverable {
    pub id: String,
    pub target_ref: String,
}

/// The declared set of a Warrant, read from its `deliverables.toml`, sorted
/// by id so two readers agree on the digest.
pub fn declared_set(
    repo: &Repository,
    dir: &camino::Utf8Path,
) -> Result<Vec<OwnedDeliverable>, RepoError> {
    let mut set: Vec<OwnedDeliverable> = repo
        .load_deliverables(dir)?
        .records
        .iter()
        .map(|d| OwnedDeliverable {
            id: d.id.clone(),
            target_ref: d.target_ref.clone(),
        })
        .collect();
    set.sort();
    Ok(set)
}

/// sha256 over the RFC 8785 rendering of `[[id, target_ref], …]`, sorted by
/// id. Documented here rather than registered as a digest domain: it is a
/// fingerprint of a list, not a canonical artifact, and the compiler's domain
/// table is for things a foreign verifier recomputes.
#[must_use]
pub fn set_digest(set: &[OwnedDeliverable]) -> String {
    let mut sorted: Vec<&OwnedDeliverable> = set.iter().collect();
    sorted.sort();
    let pairs: Vec<[&str; 2]> = sorted
        .iter()
        .map(|d| [d.id.as_str(), d.target_ref.as_str()])
        .collect();
    let jcs = serde_jcs::to_string(&pairs).unwrap_or_default();
    format!(
        "sha256:{}",
        openwarrant_compiler::sha256_hex(jcs.as_bytes())
    )
}

/// One Warrant's claim on one path, as its authorization recorded it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Owner {
    pub alias: String,
    pub deliverable_id: String,
    /// The authorization's effective time — the ordering key. §67.2 calls a
    /// locally stamped time provisional; `authorize` refuses a time that
    /// precedes an existing owner of the same path so the order seen is the
    /// order recorded.
    pub authorized_at: String,
    pub resolved: bool,
}

/// Every governed path in the corpus, newest owner first.
#[derive(Debug, Default, Clone)]
pub struct Ownership {
    by_path: BTreeMap<String, Vec<Owner>>,
}

/// Indexes this process has built, by the [`fingerprint`] of their inputs.
static INDEXES: std::sync::OnceLock<
    std::sync::Mutex<std::collections::HashMap<String, Ownership>>,
> = std::sync::OnceLock::new();

/// Every file the index reads, as (path, length, modification time in
/// nanoseconds): each Warrant's top-level records, `atoms/` and
/// `amendments/`; the authority register, allowed signers, responses and
/// batches; the SAS revisions; `openwarrant.toml`. `None` when any of it
/// cannot be read — then nothing is cached and the index is built fresh.
fn fingerprint(repo: &Repository) -> Option<String> {
    fn add(out: &mut Vec<u8>, path: &std::path::Path) -> Option<()> {
        let meta = std::fs::metadata(path).ok()?;
        if meta.is_dir() {
            let mut entries: Vec<_> = std::fs::read_dir(path)
                .ok()?
                .filter_map(Result::ok)
                .map(|e| e.path())
                .filter(|p| p.is_file())
                .collect();
            entries.sort();
            for e in entries {
                add(out, &e)?;
            }
            return Some(());
        }
        let mtime = meta
            .modified()
            .ok()?
            .duration_since(std::time::UNIX_EPOCH)
            .ok()?
            .as_nanos();
        out.extend_from_slice(path.as_os_str().as_encoded_bytes());
        out.extend_from_slice(&meta.len().to_le_bytes());
        out.extend_from_slice(&mtime.to_le_bytes());
        out.push(0);
        Some(())
    }
    let root = repo.root.as_std_path();
    let mut out = Vec::new();
    add(&mut out, &root.join("openwarrant.toml"))?;
    // `docs/authority/standing` (OW-ADR-0029): a covered authorization is
    // believed only while its class file and the class's signed responses
    // are what they were, so the index is keyed by them too.
    for d in [
        "docs/authority",
        "docs/authority/responses",
        "docs/authority/batches",
        "docs/authority/standing",
    ] {
        let p = root.join(d);
        if p.is_dir() {
            add(&mut out, &p)?;
        }
    }
    let sas = repo.sas_revisions_dir();
    if sas.is_dir() {
        add(&mut out, sas.as_std_path())?;
    }
    let mut dirs = repo.warrant_dirs().ok()?;
    dirs.sort();
    for dir in dirs {
        let dir = dir.as_std_path();
        add(&mut out, dir)?;
        for sub in ["atoms", "amendments"] {
            let p = dir.join(sub);
            if p.is_dir() {
                add(&mut out, &p)?;
            }
        }
    }
    Some(openwarrant_compiler::sha256_hex(&out))
}

impl Ownership {
    /// Read every authorized Warrant with a recorded, attested set.
    ///
    /// Skipped, and therefore never owners: records with no `owned` set
    /// (legacy), records whose revision is not authorized, records whose
    /// authorize signature does not verify against the register, Warrants
    /// whose DERIVED currency is `superseded` (OW-ADR-0022: an authorized
    /// successor's `supersedes`, never a field), and Warrants whose resolution
    /// standing is annulled.
    ///
    /// Memoized for the process by [`fingerprint`]: `war compile` built this
    /// index once per pending act it judged — the whole corpus loaded dozens
    /// of times over. Any write to what the index reads moves the
    /// fingerprint, and the next call rebuilds.
    pub fn index(repo: &Repository) -> Result<Self, RepoError> {
        let key = fingerprint(repo);
        if let Some(key) = &key
            && let Some(hit) = INDEXES
                .get_or_init(Default::default)
                .lock()
                .ok()
                .and_then(|m| m.get(key).cloned())
        {
            return Ok(hit);
        }
        let corpus: Vec<crate::repo::Loaded> = repo
            .warrant_dirs()?
            .iter()
            .filter_map(|d| repo.load_warrant(d).ok())
            .collect();
        let built = Self::index_with(repo, &crate::relations::currencies(&corpus))?;
        if let Some(key) = key
            && let Ok(mut m) = INDEXES.get_or_init(Default::default).lock()
        {
            m.insert(key, built.clone());
        }
        Ok(built)
    }

    /// [`Self::index`] over a currency derivation the caller already holds,
    /// so `war check` derives it once for the corpus.
    pub fn index_with(
        repo: &Repository,
        currencies: &crate::relations::Currencies,
    ) -> Result<Self, RepoError> {
        let mut by_path: BTreeMap<String, Vec<Owner>> = BTreeMap::new();
        for dir in repo.warrant_dirs()? {
            let Some(alias) = dir.file_name().map(str::to_owned) else {
                continue;
            };
            let Some(record) = repo.load_authorization(&dir)? else {
                continue;
            };
            if record.owned.is_empty() {
                continue;
            }
            if record.revision.state != openwarrant_core::RevisionState::Authorized {
                continue;
            }
            let Some(auth) = &record.revision.authorization else {
                continue;
            };
            if !crate::authority_check::verify(
                repo,
                crate::authority_check::Act::Authorize,
                &alias,
                &auth.authorizer,
                Some(&record.revision.contract_digest),
            )
            .is_signed()
            {
                continue;
            }
            if matches!(
                currencies.of(&alias),
                crate::relations::Derived::Superseded { .. }
            ) {
                continue;
            }
            let resolution = repo.load_resolution(&dir)?;
            if resolution.as_ref().is_some_and(|r| {
                r.resolution.standing == openwarrant_core::ResolutionStanding::Annulled
            }) {
                continue;
            }
            let resolved = resolution.is_some();
            for d in &record.owned {
                by_path
                    .entry(d.target_ref.clone())
                    .or_default()
                    .push(Owner {
                        alias: alias.clone(),
                        deliverable_id: d.id.clone(),
                        authorized_at: auth.effective_time.clone(),
                        resolved,
                    });
            }
        }
        for owners in by_path.values_mut() {
            owners.sort_by(|a, b| {
                b.authorized_at
                    .cmp(&a.authorized_at)
                    .then_with(|| b.alias.cmp(&a.alias))
            });
        }
        Ok(Self { by_path })
    }

    /// The Warrant that governs `path` now, if any.
    #[must_use]
    pub fn current(&self, path: &str) -> Option<&Owner> {
        self.by_path.get(path).and_then(|v| v.first())
    }

    /// A governing Warrant other than `alias`, authorized later than `alias`
    /// was — the fact that makes `alias`'s pin on `path` historical. A Warrant
    /// with no recorded authorization time (legacy) is treated as authorized at
    /// the beginning of time, so any recorded owner is newer.
    #[must_use]
    pub fn newer_than(
        &self,
        path: &str,
        alias: &str,
        alias_authorized_at: Option<&str>,
    ) -> Option<&Owner> {
        let cur = self.current(path)?;
        if cur.alias == alias {
            return None;
        }
        match alias_authorized_at {
            Some(t) if cur.authorized_at.as_str() <= t => None,
            _ => Some(cur),
        }
    }

    /// OW-ADR-0029 with Q-003 (refuse, as recommended): the owner a Warrant
    /// covered by a standing authorization may NOT take `path` from — an
    /// authorized Warrant other than `alias` that has not resolved. Routine
    /// work never silently takes a file from work in flight; the in-flight
    /// Warrant resolves first, or the routine change is signed on its own.
    /// A resolved owner is not in flight: its pin becomes historical under
    /// OW-ADR-0021 exactly as for a signed Warrant.
    #[must_use]
    pub fn in_flight_owner(&self, path: &str, alias: &str) -> Option<&Owner> {
        self.current(path)
            .filter(|owner| owner.alias != alias && !owner.resolved)
    }

    /// Every owner of `path`, oldest first — the lineage `war pins --history`
    /// renders.
    #[must_use]
    pub fn lineage(&self, path: &str) -> Vec<&Owner> {
        let mut v: Vec<&Owner> = self
            .by_path
            .get(path)
            .map(|o| o.iter().collect())
            .unwrap_or_default();
        v.reverse();
        v
    }

    /// Paths governed by anyone, for tests and the hook.
    pub fn paths(&self) -> impl Iterator<Item = &str> {
        self.by_path.keys().map(String::as_str)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_set_digest_ignores_declaration_order() {
        let a = vec![
            OwnedDeliverable {
                id: "D-002".into(),
                target_ref: "b.rs".into(),
            },
            OwnedDeliverable {
                id: "D-001".into(),
                target_ref: "a.rs".into(),
            },
        ];
        let b = vec![a[1].clone(), a[0].clone()];
        assert_eq!(set_digest(&a), set_digest(&b));
        assert!(set_digest(&a).starts_with("sha256:"));
        assert_eq!(set_digest(&a).len(), 7 + 64);
    }

    #[test]
    fn the_set_digest_moves_when_a_path_is_added() {
        let mut a = vec![OwnedDeliverable {
            id: "D-001".into(),
            target_ref: "a.rs".into(),
        }];
        let before = set_digest(&a);
        a.push(OwnedDeliverable {
            id: "D-002".into(),
            target_ref: "b.rs".into(),
        });
        assert_ne!(before, set_digest(&a));
    }

    fn owner(alias: &str, at: &str) -> Owner {
        Owner {
            alias: alias.into(),
            deliverable_id: "D-001".into(),
            authorized_at: at.into(),
            resolved: false,
        }
    }

    #[test]
    fn the_latest_authorization_governs_and_the_earlier_pin_is_historical() {
        let mut o = Ownership::default();
        o.by_path.insert(
            "x.rs".into(),
            vec![
                owner("OW-WAR-0112", "2026-09-22T10:00:00Z"),
                owner("OW-WAR-0005", "2026-09-01T10:00:00Z"),
            ],
        );
        assert_eq!(o.current("x.rs").unwrap().alias, "OW-WAR-0112");
        assert_eq!(
            o.newer_than("x.rs", "OW-WAR-0005", Some("2026-09-01T10:00:00Z"))
                .unwrap()
                .alias,
            "OW-WAR-0112"
        );
        assert!(
            o.newer_than("x.rs", "OW-WAR-0112", Some("2026-09-22T10:00:00Z"))
                .is_none()
        );
        // A legacy Warrant with no recorded time is older than any owner.
        assert!(o.newer_than("x.rs", "OW-WAR-0001", None).is_some());
        assert_eq!(
            o.lineage("x.rs")
                .iter()
                .map(|w| w.alias.as_str())
                .collect::<Vec<_>>(),
            ["OW-WAR-0005", "OW-WAR-0112"]
        );
    }

    #[test]
    fn a_covered_warrant_may_not_take_a_path_from_work_in_flight() {
        let mut o = Ownership::default();
        o.by_path.insert(
            "x.rs".into(),
            vec![owner("OW-WAR-0200", "2026-09-22T10:00:00Z")],
        );
        assert_eq!(
            o.in_flight_owner("x.rs", "OW-WAR-0201")
                .map(|w| w.alias.as_str()),
            Some("OW-WAR-0200")
        );
        assert!(o.in_flight_owner("x.rs", "OW-WAR-0200").is_none());
        o.by_path.get_mut("x.rs").expect("path")[0].resolved = true;
        assert!(o.in_flight_owner("x.rs", "OW-WAR-0201").is_none());
    }

    #[test]
    fn an_ungoverned_path_has_no_owner() {
        let o = Ownership::default();
        assert!(o.current("nothing").is_none());
        assert!(o.newer_than("nothing", "OW-WAR-0001", None).is_none());
    }
}

// SPDX-License-Identifier: Apache-2.0
//! The generated Warrant Overview — the corpus-wide status projection (SAS §17.5
//! `status`, §20.4).
//!
//! This is the list work gets knocked off. It is compiled from the Warrants
//! themselves, so it cannot claim a Warrant exists that does not, or omit one
//! that does — which is exactly the failure a hand-maintained roadmap has.
//!
//! # Status is real, and it is derived
//!
//! §24's five dimensions are implemented (OW-WAR-0008), so the status column is
//! no longer absent. It reports `derived` rather than `recorded` because nothing
//! journals transitions yet (OW-WAR-0031), and every Warrant derives to `draft`
//! because authorization does not exist until OW-WAR-0009.
//!
//! Forty Warrants all reading `draft` is the honest answer, not a bug.
//!
//! **Milestone progress.** Milestones now parse (OW-WAR-0007), so the column
//! reports how many are DECLARED — never how many are met. Completion needs the
//! state model and gate runs, and a column that looked like progress would be
//! read as progress.

use std::collections::BTreeSet;
use std::fmt::Write as _;

use serde::Serialize;

/// One Warrant, as much as can be honestly reported today.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct WarrantSummary {
    pub alias: String,
    pub uuid: String,
    pub title: String,
    pub profile: String,
    pub assurance_level: String,
    /// `sas://` refs from `[[implements]]`.
    pub implements: Vec<String>,
    /// `roadmap://` refs.
    pub roadmap: Vec<String>,
    /// Parent aliases where resolvable in this corpus, else the raw ref.
    pub parents: Vec<String>,
    pub atom_count: usize,
    pub source: String,
    /// `(milestones, stages)` when the graph parses. Still NOT whether any
    /// milestone is MET — that needs the state model (OW-WAR-0008) and gate runs
    /// (OW-WAR-0020). A count of declarations is not a count of achievements.
    pub milestone_count: Option<(usize, usize)>,
    /// The five §24 dimensions, with provenance. Derived until OW-WAR-0031.
    pub state: openwarrant_core::WarrantState,
    /// The currency DERIVED from the relations around this Warrant
    /// (OW-ADR-0022) — `superseded` when an authorized Warrant declares
    /// `supersedes` → it. Rendered in place of `state.currency`, which a
    /// journal cannot know: supersession is recorded on the successor.
    pub currency: String,
}

/// Render the Warrant Overview.
pub fn render(summaries: &[WarrantSummary]) -> String {
    let mut sorted: Vec<&WarrantSummary> = summaries.iter().collect();
    sorted.sort_by(|a, b| a.alias.cmp(&b.alias));

    let mut out = String::new();
    out.push_str(
        "<!--\nGENERATED BY OPENWARRANT. DO NOT EDIT.\nSource: the Warrants under the configured warrants path.\n-->\n\n",
    );
    out.push_str("# Warrant Overview\n\n");

    if sorted.is_empty() {
        out.push_str("No Warrants are recorded yet.\n");
        return out;
    }

    let _ = writeln!(out, "{} Warrant(s) in this repository.\n", sorted.len());

    out.push_str("## Summary\n\n");
    out.push_str("| Warrant | Title | Phase | Currency | Standing | Assurance | Milestones |\n");
    out.push_str("|---|---|---|---|---|---|---|\n");
    for w in &sorted {
        let _ = writeln!(
            out,
            "| [{alias}]({source}) | {title} | `{phase}` | `{currency}` | `{standing}` | `{assurance}` | {ms} |",
            alias = w.alias,
            source = w.source,
            title = w.title,
            phase = w.state.phase,
            currency = w.currency,
            standing = w.state.standing,
            assurance = w.assurance_level,
            ms = match w.milestone_count {
                Some((m, st)) => format!("{m}M / {st}S"),
                None => "—".to_owned(),
            },
        );
    }

    // State provenance, stated once rather than repeated per row.
    let derived = sorted
        .iter()
        .filter(|w| w.state.provenance == openwarrant_core::Provenance::Derived)
        .count();
    if derived > 0 {
        let _ = write!(
            out,
            "\n> **{derived} of {} states are DERIVED, not recorded.** Nothing journals \
             transitions yet (OW-WAR-0031), and authorization does not exist until \
             OW-WAR-0009 — so no Warrant has left `draft`. A later phase would have to \
             be invented.\n",
            sorted.len()
        );
    }

    // Requirement coverage. This is a claim about which requirements a Warrant
    // SAYS it implements — not about whether it does. §34.3 makes requirement
    // status a separate thing from a Warrant's own assertion, and conflating the
    // two would let a manifest grant itself coverage.
    let mut claimed: BTreeSet<String> = BTreeSet::new();
    for w in &sorted {
        for r in &w.implements {
            claimed.insert(r.trim_start_matches("sas://").to_owned());
        }
    }
    let _ = write!(
        out,
        "\n## Claimed SAS requirement coverage\n\n\
         {} distinct requirement(s) are claimed by at least one Warrant.\n\n",
        claimed.len()
    );
    out.push_str(
        "> **Claimed, not verified.** A Warrant declaring `[[implements]]` is an \
         assertion by its author. §34.3 treats requirement status as a separate \
         record; nothing here checks that the requirement is actually met.\n\n",
    );
    for r in &claimed {
        let by: Vec<&str> = sorted
            .iter()
            .filter(|w| {
                w.implements
                    .iter()
                    .any(|i| i.trim_start_matches("sas://") == r)
            })
            .map(|w| w.alias.as_str())
            .collect();
        let _ = writeln!(out, "- `{r}` — {}", by.join(", "));
    }

    out.push_str("\n## Relations\n\n");
    for w in &sorted {
        if w.parents.is_empty() && w.roadmap.is_empty() {
            continue;
        }
        let _ = write!(out, "- **{}**", w.alias);
        if !w.parents.is_empty() {
            let _ = write!(out, " · parent: {}", w.parents.join(", "));
        }
        if !w.roadmap.is_empty() {
            let _ = write!(out, " · roadmap: {}", w.roadmap.join(", "));
        }
        out.push('\n');
    }

    let recorded = sorted
        .iter()
        .filter(|w| w.state.provenance == openwarrant_core::Provenance::Recorded)
        .count();
    out.push_str("\n## Not reported here\n\n");
    if derived > 0 {
        let _ = writeln!(
            out,
            "- **Recorded state.** {derived} phase(s) are DERIVED from the record's shape, \
             not read from a journalled transition; {recorded} are read from a journal \
             (§66, OW-WAR-0031)."
        );
    } else {
        let _ = writeln!(
            out,
            "- **Recorded state.** Every phase is read from the Warrant's journal (§66, \
             OW-WAR-0031); a `backfilled` event is a reconstruction from records, and \
             says so in its payload."
        );
    }
    out.push_str(
        "- **Milestone progress** — the column counts DECLARED milestones and \
         stages. Nothing here says any of them is met.\n\
         - **Resolution** — a phase of `resolved` is read from a §56.2 record; every \
         other phase says nothing about whether a Warrant is done.\n",
    );

    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn w(alias: &str, implements: &[&str]) -> WarrantSummary {
        WarrantSummary {
            alias: alias.to_owned(),
            uuid: format!("uuid-{alias}"),
            title: format!("Title of {alias}"),
            profile: "delivery".to_owned(),
            assurance_level: "basic".to_owned(),
            implements: implements.iter().map(|s| format!("sas://{s}")).collect(),
            roadmap: vec!["roadmap://OW-PHASE-1/x".to_owned()],
            parents: vec![],
            atom_count: 5,
            source: format!("docs/warrants/{alias}/manifest.toml"),
            milestone_count: Some((3, 3)),
            state: openwarrant_core::WarrantState::draft(openwarrant_core::Provenance::Derived),
            currency: "current".to_owned(),
        }
    }

    #[test]
    fn the_currency_column_is_the_derived_one() {
        let mut old = w("OW-WAR-0001", &[]);
        old.currency = "superseded".to_owned();
        let out = render(&[old]);
        assert!(out.contains("| `superseded` |"), "{out}");
    }

    #[test]
    fn lists_every_warrant() {
        let out = render(&[w("OW-WAR-0001", &["RQ-070"]), w("OW-WAR-0002", &["RQ-010"])]);
        assert!(out.contains("2 Warrant(s)"));
        assert!(out.contains("OW-WAR-0001"));
        assert!(out.contains("OW-WAR-0002"));
    }

    #[test]
    fn requirement_coverage_attributes_each_requirement_to_its_warrants() {
        let out = render(&[
            w("OW-WAR-0001", &["RQ-070", "RQ-064"]),
            w("OW-WAR-0002", &["RQ-070"]),
        ]);
        assert!(out.contains("2 distinct requirement(s)"));
        // RQ-070 is claimed by both and must name both.
        let line = out
            .lines()
            .find(|l| l.starts_with("- `RQ-070`"))
            .expect("coverage line");
        assert!(line.contains("OW-WAR-0001") && line.contains("OW-WAR-0002"));
    }

    /// The overview must not imply it verified anything.
    #[test]
    fn coverage_is_labelled_as_claimed_not_verified() {
        let out = render(&[w("OW-WAR-0001", &["RQ-070"])]);
        assert!(out.contains("Claimed, not verified"));
    }

    /// The status column is real now (OW-WAR-0008), and its DERIVED provenance
    /// must be stated — otherwise a derived phase reads as a recorded one.
    ///
    /// This test replaced `no_lifecycle_status_is_rendered`, which asserted the
    /// column's absence. That test failed the moment the column arrived, which
    /// is a test doing its job: the behaviour changed, so the assertion had to.
    #[test]
    fn derived_state_is_reported_and_labelled_derived() {
        let out = render(&[w("OW-WAR-0001", &["RQ-070"])]);
        assert!(out.contains("| `draft` |"), "the phase is reported");
        assert!(
            out.contains("DERIVED, not recorded"),
            "provenance must be stated, or a derived phase reads as recorded"
        );
    }

    /// A recorded state must not carry the derived banner.
    #[test]
    fn recorded_state_is_not_labelled_derived() {
        let mut only = w("OW-WAR-0001", &["RQ-070"]);
        only.state = openwarrant_core::WarrantState::draft(openwarrant_core::Provenance::Recorded);
        let out = render(&[only]);
        assert!(
            !out.contains("DERIVED, not recorded"),
            "a recorded state must not be disclaimed as derived"
        );
    }

    #[test]
    fn output_is_independent_of_input_order() {
        let a = w("OW-WAR-0001", &["RQ-070"]);
        let b = w("OW-WAR-0002", &["RQ-010"]);
        assert_eq!(render(&[a.clone(), b.clone()]), render(&[b, a]));
    }

    #[test]
    fn an_empty_corpus_says_so() {
        assert!(render(&[]).contains("No Warrants are recorded yet."));
    }
}

// SPDX-License-Identifier: Apache-2.0
//! The master document, `docs/generated/CURRENT.md` (OW-ADR-0022).
//!
//! One document, current by construction: every current subject fully
//! expanded, atom by atom in role order, verbatim; the SAS in force by its
//! normative statements; the accepted decisions; who governs each path; who
//! may sign; and the queue with every signing command already judged by the
//! dry run. A replaced subject is one line of lineage and nothing else.
//!
//! This module is pure: it renders a [`Corpus`] the CLI gathered from the
//! records. It decides nothing about currency — the corpus arrives with each
//! subject's currency already derived from its relations
//! (`relations::currencies`), and a second computation here would be a second
//! answer.
//!
//! # Where a role is tied to a rendering
//!
//! [`ROLE_SECTIONS`] is the only place. An atom carries its relation to the
//! projections by naming a role. A namespaced optional extension role (§16.4,
//! `x.review`) has no row: its atoms render verbatim under their role name in
//! the subject's *Extensions* section, after every row (OW-WAR-0113 AM-002).
//! Any other role no row names is refused by `war check`
//! (`atom.role-unprojected`), because an atom nothing renders is text nobody
//! reads. [`is_rendered_role`] is that test, shared by both.
//!
//! # Adding a section
//!
//! [`SECTIONS`] is the order; [`Section`] names each; `render` calls one
//! function per variant. A new section is a variant, a function, and a place
//! in the list — nothing else moves; the Roadmap (OW-WAR-0114 M5) was added
//! that way.

use std::fmt::Write as _;

/// One row of the profile's role→section map.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RoleRow {
    /// The role as a manifest names it.
    pub role: &'static str,
    /// The heading this role's atoms render under, within a subject, in both
    /// projections.
    pub heading: &'static str,
}

/// The composition table (§16.1, §16.2): the roles an authored or bound atom
/// may carry, in the order a subject renders them. `control` and
/// `relations_and_integrity` are compiler-produced sections with no atom, so
/// they have no row.
pub const ROLE_SECTIONS: &[RoleRow] = &[
    RoleRow {
        role: "intent",
        heading: "Intent",
    },
    RoleRow {
        role: "basis",
        heading: "Basis",
    },
    RoleRow {
        role: "adr",
        heading: "Decision",
    },
    RoleRow {
        role: "work_order",
        heading: "Work order",
    },
    RoleRow {
        role: "milestones",
        heading: "Milestones",
    },
    RoleRow {
        role: "execution",
        heading: "Execution",
    },
    RoleRow {
        role: "assurance",
        heading: "Assurance",
    },
    RoleRow {
        role: "resolution",
        heading: "Resolution",
    },
    RoleRow {
        role: "validation",
        heading: "Validation",
    },
];

/// The row that renders `role`, if any projection renders it.
#[must_use]
pub fn role_row(role: &str) -> Option<(usize, &'static RoleRow)> {
    ROLE_SECTIONS
        .iter()
        .enumerate()
        .find(|(_, r)| r.role == role)
}

/// Whether a projection renders an atom of `role`: a row of
/// [`ROLE_SECTIONS`] names it, or it is a namespaced extension role (§16.4),
/// which renders under *Extensions*. The namespace test is the manifest's
/// own ([`openwarrant_core::is_namespaced_extension_role`]), so what the
/// grammar accepts (G-M8) and what the projections render cannot drift apart.
#[must_use]
pub fn is_rendered_role(role: &str) -> bool {
    role_row(role).is_some() || openwarrant_core::is_namespaced_extension_role(role)
}

/// The heading a subject's extension atoms render under.
pub const EXTENSIONS_HEADING: &str = "Extensions";

/// Where the master document is written, relative to the repository root.
pub const CURRENT_PATH: &str = "docs/generated/CURRENT.md";
/// Where the history is written, relative to the repository root.
pub const HISTORY_PATH: &str = "docs/generated/HISTORY.md";

/// One atom of a subject, as the records hold it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Atom {
    pub ordinal: u32,
    pub role: String,
    /// Repository-relative path.
    pub source: String,
    /// The atom's text after its frontmatter, byte for byte.
    pub body: String,
    /// A structured atom (YAML) renders fenced; Markdown renders inline.
    pub structured: bool,
}

/// One declared deliverable and the state of its digest.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Deliverable {
    pub id: String,
    pub title: String,
    pub target_ref: String,
    pub digest: String,
}

/// One Warrant.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Subject {
    pub alias: String,
    pub title: String,
    /// Repository-relative manifest path.
    pub manifest: String,
    pub profile: String,
    /// The DERIVED currency: `current`, `superseded`, `annulled`,
    /// `deprecated`.
    pub currency: String,
    /// For a superseded subject, the Warrant(s) whose relation replaced it.
    pub replaced_by: Option<String>,
    /// The roadmap phase this subject belongs to, by id.
    pub phase: Option<String>,
    pub rung: String,
    /// The SAS revision the authorization names, when authorized.
    pub basis_revision: Option<String>,
    pub contract_revision: Option<u32>,
    pub contract_digest: Option<String>,
    /// Repository-relative record paths, when they exist.
    pub authorization: Option<String>,
    pub resolution: Option<String>,
    pub atoms: Vec<Atom>,
    pub deliverables: Vec<Deliverable>,
}

impl Subject {
    #[must_use]
    pub fn is_current(&self) -> bool {
        self.currency == "current"
    }

    /// Atoms in role order, then ordinal.
    #[must_use]
    pub fn atoms_in_role_order(&self) -> Vec<&Atom> {
        let mut atoms: Vec<&Atom> = self.atoms.iter().collect();
        atoms.sort_by_key(|a| (role_row(&a.role).map_or(usize::MAX, |(i, _)| i), a.ordinal));
        atoms
    }
}

