    #[test]
    fn adoption_is_absent_unless_recorded() {
        let config = valid();
        let text = toml::to_string_pretty(&config).expect("serializes");
        assert!(!text.contains("adoption"), "{text}");
        let back: RepositoryConfig = toml::from_str(&text).expect("parses");
        assert_eq!(back.adoption, None);
        let mut adopted = valid();
        adopted.adoption = Some(AdoptionPolicy {
            baseline: "0123456789abcdef0123456789abcdef01234567".to_owned(),
        });
        let text = toml::to_string_pretty(&adopted).expect("serializes");
        assert!(text.contains("[adoption]"), "{text}");
        let back: RepositoryConfig = toml::from_str(&text).expect("parses");
        assert_eq!(back, adopted);
    }

    /// OW-WAR-0138: absent means no, a written config omits it while false,
    /// and a human's `true` reads back.
    #[test]
    fn user_presence_is_off_unless_written() {
        let config = valid();
        assert!(!config.policy.require_user_presence);
        let text = toml::to_string_pretty(&config).expect("serializes");
        assert!(!text.contains("require_user_presence"), "{text}");
        let on: AuthorityPolicy = toml::from_str("require_user_presence = true\n").expect("parses");
        assert!(on.require_user_presence);
        assert!(!on.allow_automated_resolution);
        let text = toml::to_string_pretty(&on).expect("serializes");
        assert!(text.contains("require_user_presence = true"), "{text}");
    }

    #[test]
    fn empty_path_is_refused() {
        let mut config = valid();
        config.paths.adrs = "  ".to_owned();
        assert_eq!(
            config.validate(),
            Err(ConfigError::PathEmpty { field: "adrs" })
        );
    }

    /// OW-WAR-0132 U-001: absent is refusal, not consent; 0 is the default.
    #[test]
    fn perform_spend_and_attempt_defaults() {
        let p = PerformPolicy::default();
        assert!(
            !p.unmetered_allowed(),
            "absent allow_unmetered is not consent"
        );
        assert_eq!((p.repairs(), p.recoveries()), (3, 2));
        let set: PerformPolicy = toml::from_str(
            "allow_unmetered = true\nhard_spend_cap = \"1.00 USD\"\nmax_repairs = 1\nmax_recoveries = 5\n",
        )
        .expect("parses");
        assert!(set.unmetered_allowed());
        assert_eq!(set.hard_spend_cap.as_deref(), Some("1.00 USD"));
        assert_eq!((set.repairs(), set.recoveries()), (1, 5));
        assert!(!set.is_empty());
        let no: PerformPolicy = toml::from_str("allow_unmetered = false\n").expect("parses");
        assert!(!no.unmetered_allowed());
        assert!(
            !no.is_empty(),
            "an explicit false is written back, not dropped"
        );
    }
}

// SPDX-License-Identifier: Apache-2.0
//! `war check` — deterministic, agent-free validation (SAS §71.7, RQ-074).
//!
//! No model, no network, no clock. Reproducibility is not a nicety here: a
//! checker whose verdict can vary is not a control.
//!
//! That was once guaranteed by the binary having no HTTP client at all. Since
//! OW-WAR-0044 it is guaranteed by this module not using the one it has: `ureq`
//! is linked for the §67 Knowledge Fabric seam, and `war kf` is the only
//! command that dials. `war check` reaching the network would make its verdict
//! depend on someone else's uptime, which is the opposite of a control.

use std::collections::{BTreeMap, BTreeSet};

use openwarrant_compiler::{ChildRef, lower};
use openwarrant_core::{ValidatedManifest, detect_parent_cycles, milestones, obligation, seam};

use crate::compile::{adr_overview, projections, warrant_overview};

// OW-WAR-0119: the corpus identity rules. A child of this module, not a
// sibling in `lib.rs`, because `war check` is their only caller.
#[path = "identity_check.rs"]
mod identity_check;
use crate::diagnostic::{Diagnostic, Report, Severity};
use crate::repo::{Loaded, RepoError, Repository};

/// OW-WAR-0137 — a Warrant's review assignment against what its authorizer
/// signed, named by rule. An assignment edited, added or removed after
/// signing (`assignment.moved`) or one that does not parse
/// (`assignment.malformed`) is an ERROR: nobody may take the act it governs
/// until a human restores or re-authorizes it. An assignee who has since lost
/// the role is a WARN (`assignment.role-revoked`): the act waits, and nobody
/// else is substituted. A Warrant with no assignment reports nothing.
fn check_assignment(
    repo: &Repository,
    one: &Loaded,
    register: Option<&openwarrant_core::authority::AuthorityRegister>,
    report: &mut Report,
) {
    use crate::authorize::assignment::{self, Standing};
    let alias = one.alias();
    let file = repo.relative(&one.dir.join(assignment::FILE));
    let standing = match crate::authorize::assignment_standing(repo, &one.dir) {
        Ok(s) => s,
        Err(e) => {
            report.push(Diagnostic::unknown(
                "assignment.unreadable",
                file,
                format!("{alias}: the assignment's standing could not be read: {e}"),
            ));
            return;
        }
    };
    match standing {
        Standing::None => {}
        Standing::Moved { .. } | Standing::Malformed(_) => {
            if let Err(f) = standing.for_act(assignment::Act::Resolve) {
                report.push(Diagnostic::error(
                    f.rule,
                    file,
                    format!("{alias}: {}", f.message),
                ));
            }
        }
        Standing::Unsigned(ref a) | Standing::Signed(ref a) => {
            let signed = matches!(standing, Standing::Signed(_));
            let findings = register
                .map(|r| assignment::validate(a, r, &repo.performer()))
                .unwrap_or_default();
            for f in &findings {
                // Before signing, `war authorize` will refuse it; after, the
                // register moved under a signed assignment.
                let rule = if signed && f.rule == "assignment.role-missing" {
                    "assignment.role-revoked"
                } else {
                    f.rule
                };
                report.push(Diagnostic::warn(
                    rule,
                    file.clone(),
                    format!("{alias}: {}", f.message),
                ));
            }
            if findings.is_empty() {
                report.push(Diagnostic::pass(
                    if signed {
                        "assignment.signed"
                    } else {
                        "assignment.proposed"
                    },
                    format!(
                        "{alias}: {} {}",
                        a.digest(),
                        if signed {
                            "is the assignment the authorizer signed"
                        } else {
                            "awaits the authorizer's signature"
                        }
                    ),
                ));
            }
        }
    }
}

/// Run every Phase 1 check over the whole corpus, or one Warrant.
pub fn run(
    repo: &Repository,
    only: Option<&str>,
    check_generated: bool,
) -> Result<Report, RepoError> {
    let dirs = match only {
        Some(alias) => vec![repo.warrant_dir(alias)?],
        None => repo.warrant_dirs()?,
    };

    let mut report = Report::default();
    let mut undisposed_warrants = 0usize;
    let mut total_warrants = 0usize;

    if dirs.is_empty() {
        report.push(Diagnostic::warn(
            "corpus.empty",
            repo.config.paths.warrants.clone(),
            "no Warrants found; nothing to check",
        ));
        return Ok(report);
    }

    let mut loaded = Vec::new();
    for dir in &dirs {
        let one = repo.load_warrant(dir)?;
        loaded.push(one);
    }

    // OW-WAR-0121: a temp file of the atomic write path is a write that
    // stopped before its rename. The record it was meant to replace is whole
    // (old or absent); the temp file is named so a person can remove it.
    check_stray_temps(repo, only.map(|_| dirs.as_slice()), &mut report);

    // A parent's contract digest is computed from the parent, so verifying a
    // child's citation needs the whole corpus in hand. When only one Warrant was
    // requested, load the rest read-only so the citation can still be checked
    // rather than reported as unknowable.
    let corpus = if only.is_some() {
        let mut all = Vec::new();
        for dir in repo.warrant_dirs()? {
            all.push(repo.load_warrant(&dir)?);
        }
        all
    } else {
        loaded.clone()
    };
    let parent_digests = contract_digests(&corpus);

    // §43.1 — local gate candidates. Loaded once for the corpus so an obligation
    // citing a gate can be resolved rather than taken on trust.
    let gates = load_gate_registry(repo, &mut report);
    report_independence(repo, &loaded, &mut report);
    // OW-WAR-0138: where the actor binding and the policy keys come from —
    // `authority.unprotected` once without a store, a divergence per key
    // with one.
    for d in crate::authority_check::protection_report(repo) {
        report.push(d);
    }

    // OW-ADR-0022: currency is derived from relations, once, over the whole
    // corpus, and read by everything below that asks it.
    let currencies = crate::relations::currencies(&corpus);

    // §20 and §21 relation conformance (OW-WAR-0043 OBL-004, §91.5 tests 30-35).
    // Built over the WHOLE corpus for the same reason parent digests are: a
    // parent/child claim is not checkable from one side of the relation.
    {
        let related: Vec<crate::relations::Related<'_>> = corpus
            .iter()
            .filter_map(|one| {
                let validated = one.validated.as_ref()?;
                let basis = one.basis.as_ref()?;
                let atom_source = basis
                    .atoms
                    .iter()
                    .map(|a| String::from_utf8_lossy(&a.bytes).into_owned())
                    .collect::<Vec<_>>()
                    .join("\n");
                Some(crate::relations::Related {
                    alias: one.alias().to_string(),
                    manifest: validated,
                    manifest_file: one.dir.join("manifest.toml").to_string(),
                    generated_view: std::fs::read_to_string(
                        one.dir.join("generated").join("WAR.md"),
                    )
                    .ok(),
                    atom_source,
                })
            })
            .collect();
        crate::relations::check(&related, &currencies, &mut report);
    }
    // OW-ADR-0023: the roadmap record, and the Warrants it holds to a phase.
    crate::roadmap_cmd::check(repo, &corpus, &mut report);
    let roadmap = crate::roadmap_cmd::load(repo).ok().flatten();

    // OW-ADR-0021: which Warrant governs each path NOW. Built once — it
    // verifies one attestation per owning Warrant, and the drift decision
    // below asks it for every content-addressed deliverable in the corpus.
    let ownership = crate::ownership::Ownership::index_with(repo, &currencies)?;
    // OW-WAR-0125: each recorded SAS revision split into sections, read from
    // the document or from history at most once per run.
    let sas_sections = crate::sas::RevisionSections::new(repo);

    let shared = Shared {
        corpus: &corpus,
        parent_digests: &parent_digests,
        gates: &gates,
        ownership: &ownership,
        roadmap: roadmap.as_ref(),
        sas_sections: &sas_sections,
    };
    // OW-WAR-0137: the register, once, for every Warrant's assignment.
    let register = repo.load_authority_register();
    for one in &loaded {
        check_one(repo, one, shared, check_generated, &mut report);
        check_assignment(repo, one, register.as_ref().ok(), &mut report);
        if let Some(basis) = &one.basis {
            total_warrants += 1;
            let fully_undisposed = basis
                .atoms
                .iter()
                .filter(|a| a.role == "assurance")
                .filter_map(|a| obligation::parse(&String::from_utf8_lossy(&a.bytes)).ok())
                .any(|set| {
                    !set.obligations.is_empty() && set.undisposed().len() == set.obligations.len()
                });
            if fully_undisposed {
                undisposed_warrants += 1;
            }
        }
    }

    // Cross-Warrant checks need the whole corpus, so they run after the loop.
    // §91.2 test 12.
    let validated: Vec<ValidatedManifest> =
        loaded.iter().filter_map(|l| l.validated.clone()).collect();
    let cycles = detect_parent_cycles(&validated);
    if cycles.is_empty() {
        report.push(Diagnostic::pass(
            "composition.acyclic",
            format!(
                "parent graph is acyclic across {} Warrant(s)",
                validated.len()
            ),
        ));
    } else {
        for cycle in cycles {
            report.push(Diagnostic::error(
                "composition.cycle",
                repo.config.paths.warrants.clone(),
                format!("parent cycle: {}", cycle.path.join(" → ")),
            ));
        }
    }

    // ADR corpus (§19). A malformed ADR is an error; the Overview is a
    // projection and drift-checks exactly like a Warrant parent (§19.7).
    let adrs = repo.load_adrs()?;
    for (path, err) in &adrs.failures {
        report.push(Diagnostic::error(
            "adr.malformed",
            path.clone(),
            err.to_string(),
        ));
    }
    if adrs.failures.is_empty() && !adrs.records.is_empty() {
        report.push(Diagnostic::pass(
            "adr.parsed",
            format!("{} ADR(s) parsed", adrs.records.len()),
        ));
    }
    // §12 identity (OW-WAR-0119), once per run: duplicates and alias
    // resolution need every Warrant and every ADR in hand, so this sits after
    // both are loaded rather than inside the per-Warrant loop.
    identity_check::check(repo, &corpus, &loaded, &adrs.records, &mut report);
    // §101 — the SAS is a controlled document. The bytes on disk are held to
    // the latest recorded revision's digest. Until OW-WAR-0058 nothing in code
    // compared them: the digest appeared in six places, all prose.
    match repo.load_sas_revisions() {
        Err(err) => report.push(Diagnostic::error(
            "sas.revision-malformed",
            repo.config.paths.sas.clone(),
            err.to_string(),
        )),
        Ok(revisions) => match crate::sas::pin_of(&revisions) {
            None => report.push(Diagnostic::warn(
                "sas.unrecorded",
                repo.config.paths.sas.clone(),
                "no SAS revision is recorded; the document is pinned by prose only. \
                 `war sas propose <version>` records one"
                    .to_owned(),
            )),
            Some(pin) => match repo.sas_document() {
                Err(err) => report.push(Diagnostic::error(
                    "sas.document",
                    repo.config.paths.sas.clone(),
                    err.to_string(),
                )),
                Ok((path, bytes)) => {
                    let actual = openwarrant_compiler::sha256_hex(&bytes);
                    if actual == pin.sha256 {
                        report.push(Diagnostic::pass(
                            "sas.pinned",
                            format!(
                                "{} matches revision {} ({}), sha256:{}",
                                repo.relative(&path),
                                pin.version,
                                pin.state,
                                &pin.sha256[..12]
                            ),
                        ));
                    } else if let Some(proposed) = revisions
                        .iter()
                        .find(|r| r.sha256 == actual && r.version != pin.version)
                    {
                        // The remedy the error names, taken: the document IS a
                        // recorded proposal awaiting a human. The accepted
                        // revision stays normative until then (§101.2).
                        report.push(Diagnostic::warn(
                            "sas.proposed-unaccepted",
                            repo.relative(&path),
                            format!(
                                "the document is revision {} ({}), sha256:{}; the accepted \
                                 revision {} remains normative until `war sign {}` accepts it",
                                proposed.version,
                                proposed.state,
                                &actual[..12],
                                pin.version,
                                proposed.version
                            ),
                        ));
                    } else {
                        report.push(Diagnostic::error(
                            "sas.digest-drift",
                            repo.relative(&path),
                            format!(
                                "the document is sha256:{actual} but revision {} ({}) records \
                                 sha256:{}. §101.6: the accepted revision is normative and mirrors \
                                 state its exact digest. Either restore the bytes or propose a \
                                 new revision — an edited document under an unchanged record is \
                                 the failure this check exists for",
                                pin.version, pin.state, pin.sha256
                            ),
                        ));
                    }
                }
            },
        },
    }

    // OW-ADR-0029: every class file — one that reaches an authority path, or
    // whose acceptance no longer verifies over its bytes, is an error.
    crate::standing_cmd::check_classes(repo, &mut report);

    // Accepting a SAS revision is the act that makes a specification normative
    // for every Warrant that pins it, so it is held to the same rule as an
    // authorization: a human signature over the acceptance response's exact
    // bytes, naming the digest of the document accepted. Leaving this act out
    // would have left one path where a record is believed for its contents.
    let sas_revisions = repo.load_sas_revisions().unwrap_or_default();
    let sas_pin = crate::sas::pin_of(&sas_revisions).map(|p| p.version.clone());
    for rev in &sas_revisions {
        let Some(acceptance) = &rev.acceptance else {
            continue;
        };
        let subject = format!("SAS-{}", rev.version);
        let verdict = crate::authority_check::verify(
            repo,
            crate::authority_check::Act::Accept,
            &subject,
            &acceptance.accepted_by,
            Some(&rev.sha256),
        );
        if verdict.is_signed() {
            report.push(Diagnostic::pass(
                "authority.signed",
                format!("{subject}: {}", verdict.why()),
            ));
        } else if sas_pin.as_deref() == Some(rev.version.as_str()) {
            report.push(Diagnostic::error(
                verdict.rule(),
                format!("docs/sas/revisions/{}.toml", rev.version),
                format!("{subject}: {}", verdict.why()),
            ));
        } else {
            // A superseded revision is normative for nothing. Its acceptance
            // predates enforcement and cannot be signed now without dating the
            // act wrongly, so it is reported and not treated as a live failure.
            report.push(Diagnostic::warn(
                verdict.rule(),
                format!("docs/sas/revisions/{}.toml", rev.version),
                format!(
                    "{subject}: superseded by {} and normative for nothing; {}",
                    sas_pin.as_deref().unwrap_or("no accepted revision"),
                    verdict.why()
                ),
            ));
        }
    }

    // Both corpus-wide projections drift-check through the same function, so
    // they cannot come to report drift differently.
    if check_generated && repo.config.generated.verify_drift {
        drift_check(
            repo,
            warrant_overview(repo),
            "warrant-overview",
            &mut report,
        );
        drift_check(repo, adr_overview(repo), "adr-overview", &mut report);
        drift_check(
            repo,
            crate::status::corpus_status_md(repo),
            "corpus-status",
            &mut report,
        );
        drift_check(
            repo,
            crate::status::corpus_status_json(repo),
            "corpus-status",
            &mut report,
        );
        drift_check(
            repo,
            crate::status::corpus_status_html(repo),
            "corpus-status",
            &mut report,
        );
        drift_check(
            repo,
            crate::timeline::corpus_timeline_json(repo),
            "corpus-timeline",
            &mut report,
        );
        drift_check(
            repo,
            crate::timeline::corpus_pending_json(repo),
            "corpus-pending",
            &mut report,
        );
        // The SAS normative projection (E1), when there is a document.
        if repo.sas_document().is_ok() {
            match crate::compile::sas_normative(repo) {
                Ok(files) => {
                    for file in files {
                        drift_check(repo, Ok(file), "sas-normative", &mut report);
                    }
                }
                Err(e) => drift_check(repo, Err(e), "sas-normative", &mut report),
            }
            // The section index (OW-WAR-0125), by the same function.
            match crate::compile::sas_sections(repo) {
                Ok(files) => {
                    for file in files {
                        drift_check(repo, Ok(file), "sas-sections", &mut report);
                    }
                }
                Err(e) => drift_check(repo, Err(e), "sas-sections", &mut report),
            }
        }
        // OW-ADR-0022: the master document, and the history when this
        // repository keeps one. `generated.drift`, the rule every projection
        // of a Warrant reports under: CURRENT.md is written by `compile` and by
        // nothing else. With `history = false` nothing is compiled for
        // HISTORY.md, so nothing is compared.
        match crate::compile::master_documents(repo) {
            Ok(files) => {
                for file in files {
                    drift_check(repo, Ok(file), "generated", &mut report);
                }
            }
            Err(e) => drift_check(repo, Err(e), "generated", &mut report),
        }
    }

    // §38.6 disposition status, aggregated once for the corpus rather than
    // blocking each Warrant. Undisposed is the normal state of planned work.
    if undisposed_warrants > 0 {
        report.note(format!(
            "{undisposed_warrants} of {total_warrants} Warrant(s) have no disposed              obligations — §38.6 yields no resolution verdict for them, which is the              expected state of work that has not been assessed"
        ));
    }

    // §28.5 coverage, reported once for the corpus. A contract digest covering
    // 8 of 17 elements is not a §28.5 contract digest, and saying so on every
    // run is what stops it being mistaken for one (OW-ADR-0004).
    let coverage = openwarrant_compiler::WarIr::current_coverage();
    if !coverage.is_complete() {
        report.note(format!(
            "contract digest covers {} of {} §28.5 elements — missing: {}",
            coverage.len(),
            openwarrant_core::ContractElement::ALL.len(),
            coverage
                .missing()
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }

    // Printed on every run including a clean one, and deliberately NOT a
    // diagnostic: a report that answers "ok" while whole classes of check go
    // unasked reads as full coverage, but a scope note that blocked readiness
    // would make the verdict permanently negative and therefore meaningless.
    report.note("gate execution — `war gate --run` executes a registered gate (§44), but `war check` does not invoke it, so nothing here is evidence that a Warrant's acceptance gates were run");
    report.note("Preflight readiness (§32.7) — 'well-formed' is a claim about the record only");
    report.note("bound-atom resolution — `ref =` atoms cannot be fetched offline");
    // Kept, and now says WHY rather than only that. OW-WAR-0049's OBL-003 asks
    // this note to match reality: the tests are not merely unimplemented, they
    // are blocked on a decision this repository has not made, and OW-ADR-0007
    // records which decision. A note that says "unchecked" without saying what
    // would change it reads as a backlog item; this one names the blocker.
    report.note(
        "Source Holder ambiguity and classification propagation (§91.2 tests 14, 15) — \
         narrowed by OW-ADR-0008: test 14 needs a `source_holder` on atoms, which §13 \
         requires and none declares; test 15 needs a classification ordering, which \
         the SAS does not give. Neither is undecided — both are undeclared",
    );
    if !check_generated {
        report.note("generated-view drift — pass --generated to compare committed projections");
    }
    if only.is_none() {
        check_roadmap_status_claims(repo, &mut report);
    }

    Ok(report)
}

/// `storage.stray-temp` (warning) for each file `atomic::stray` finds under
/// `docs/`; with one Warrant asked for, only those inside its directory.
fn check_stray_temps(
    repo: &Repository,
    within: Option<&[camino::Utf8PathBuf]>,
    report: &mut Report,
) {
    for s in crate::compile::atomic::stray(&repo.root) {
        if within.is_some_and(|dirs| !dirs.iter().any(|d| s.temp.starts_with(d))) {
            continue;
        }
        report.push(Diagnostic::warn(
            "storage.stray-temp",
            repo.relative(&s.temp),
            format!(
                "{} is a temp file left by a write that stopped before its rename; it was meant \
                 to replace {}, which is whole as it stands (the previous bytes, or absent). \
                 Nothing reads the temp file. Remove it once you know which act stopped",
                repo.relative(&s.temp),
                repo.relative(&s.record)
            ),
        ));
    }
}

/// Compare one generated corpus-wide projection against a fresh compilation.
///
/// Shared by the Warrant and ADR overviews so the two cannot drift apart in how
/// they report drift — a duplicated check is a check that gets fixed in one place.
fn drift_check(
    repo: &Repository,
    compiled: Result<(camino::Utf8PathBuf, String), RepoError>,
    rule: &str,
    report: &mut Report,
) {
    match compiled {
        Ok((path, expected)) => {
            let relative = repo.relative(&path);
            let name = path.file_name().unwrap_or("overview").to_owned();
            match std::fs::read_to_string(&path) {
                Ok(actual) if actual == expected => report.push(Diagnostic::pass(
                    format!("{rule}.drift"),
                    format!("{name} matches a fresh compilation"),
                )),
                Ok(_) => report.push(Diagnostic::error(
                    format!("{rule}.drift"),
                    relative,
                    format!(
                        "the committed {name} differs from a fresh compilation; it was \
                         edited by hand or its sources changed without recompiling"
                    ),
                )),
                Err(_) if repo.config.generated.commit => report.push(Diagnostic::error(
                    format!("{rule}.missing"),
                    relative,
                    format!(
                        "{name} is missing and this repository commits generated views; \
                         run `war compile`"
                    ),
                )),
                Err(_) => {}
            }
        }
        Err(err) => report.push(Diagnostic::error(
            format!("{rule}.compile"),
            repo.config.paths.warrants.clone(),
            err.to_string(),
        )),
    }
}

/// Contract digest per Warrant UUID, for verifying children's citations.
///
/// A Warrant that could not be validated has no contract digest and is simply
/// absent from the map; a child citing it gets an honest "cannot verify" rather
/// than a comparison against a value invented from broken sources.
fn contract_digests(corpus: &[Loaded]) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    for one in corpus {
        let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
            continue;
        };
        if let Ok(ir) = lower(basis, validated)
            && let Ok(digest) = ir.contract_digest()
        {
            out.insert(validated.uuid.to_string(), digest);
        }
    }
    out
}

/// §46.3 — report, ONCE, whether verification here meets each level's minimum.
///
/// Independence is declared per repository, so reporting it per Warrant says the
/// same sentence forty-nine times. A finding repeated once per record is a
/// finding nobody reads, which would defeat the point of surfacing it at all.
///
/// Never fatal at draft. §46.3's minimum binds when a resolution is recorded
/// (§56.1 requirement 10). A repository that could not pass its own gate on day
/// one would have the rule deleted rather than the gap closed — but silence is
/// worse, and silence is what alpha shipped: "this repository authored and
/// verified itself" was a paragraph in the roadmap that no tool could act on.
fn report_independence(repo: &Repository, loaded: &[Loaded], report: &mut Report) {
    let config_path = repo.relative(&repo.root.join("openwarrant.toml"));

    let Some(independence) = &repo.config.independence else {
        report.push(Diagnostic::warn(
            "independence.undeclared",
            config_path,
            "no independence is declared for this repository, so §46.3's minimums \
             cannot be evaluated for any Warrant. Absent is not the same as none — \
             `none` reads as examined and absent, absent reads as unexamined"
                .to_owned(),
        ));
        return;
    };

    // Group by the level actually declared, since the minimum differs per level.
    let mut by_level: BTreeMap<String, usize> = BTreeMap::new();
    for one in loaded {
        if let Some(v) = &one.validated {
            *by_level.entry(v.assurance_level.to_string()).or_insert(0) += 1;
        }
    }

    for (level, count) in by_level {
        match independence.meets(&level) {
            Ok(()) => report.push(Diagnostic::pass(
                "independence.sufficient",
                format!("{count} {level} Warrant(s): declared independence meets §46.3's minimum"),
            )),
            Err(err) => report.push(Diagnostic::warn(
                "independence.insufficient",
                config_path.clone(),
                format!("{count} {level} Warrant(s): {err}"),
            )),
        }
    }
}

/// Load `docs/gates/*.yaml` as §43.1 local candidates.
///
/// A malformed definition is an ERROR rather than a skip. A registry that
/// quietly drops the file it could not read would let every citation of that
/// gate report unresolved, or worse, let a later valid-looking file take its
/// place unnoticed.
pub(crate) fn load_gate_registry(
    repo: &Repository,
    report: &mut Report,
) -> openwarrant_core::GateRegistry {
    let mut registry = openwarrant_core::GateRegistry::default();
    let dir = repo.root.join(&repo.config.paths.gates);
    let Ok(entries) = dir.read_dir_utf8() else {
        // No gates directory is a legitimate state: a repository may declare no
        // gates. It is reported as a note so it cannot be mistaken for a
        // registry that was read and found empty.
        report.note(format!(
            "gate registry — {} does not exist, so no gate citation can be \
             resolved. §43.1 local candidates live there",
            repo.config.paths.gates
        ));
        return registry;
    };

    let mut paths: Vec<_> = entries
        .filter_map(Result::ok)
        .map(|e| e.into_path())
        .filter(|p| p.extension().is_some_and(|e| e == "yaml" || e == "yml"))
        .collect();
    paths.sort();

    for path in paths {
        let rel = repo.relative(&path);
        let Ok(text) = std::fs::read_to_string(&path) else {
            report.push(Diagnostic::error(
                "gate.unreadable",
                rel,
                "gate definition could not be read".to_owned(),
            ));
            continue;
        };
        let doc = match openwarrant_core::structured::parse(&text) {
            Ok(d) => d,
            Err(err) => {
                report.push(Diagnostic::error("gate.malformed", rel, format!("{err}")));
                continue;
            }
        };
        match openwarrant_core::gate::definition_from_structured(&doc) {
            Ok(def) => {
                let key = def.key();
                let provenance = def.provenance;
                match registry.insert(def) {
                    Ok(()) => report.push(Diagnostic::pass(
                        "gate.registered",
                        format!("{key}: {provenance}, qualified against its declared fault model"),
                    )),
                    Err(err) => {
                        report.push(Diagnostic::error("gate.duplicate", rel, format!("{err}")));
                    }
                }
            }
            Err(err) => report.push(Diagnostic::error("gate.invalid", rel, format!("{err}"))),
        }
    }
    registry
}

#[allow(clippy::too_many_arguments)]
/// §37.2 — a declared deliverable's recorded digest must still match its bytes.
///
/// # Why this belongs in `war check` and not only in `war resolve`
///
/// `war resolve` already recomputes these digests, and it caught the drift both
/// times it happened. It caught it *late*: resolve is run deliberately, by
/// someone asking about one Warrant, so a stale record sat in `main` until
/// somebody thought to look. Twice in two days an unrelated pull request edited
/// a file some Warrant had declared — once `ci.yml` under a Bonsai change, once
/// `ci.yml` again under a dependency bump — and each time OW-WAR-0001 silently
/// lost a requirement.
///
/// A record that no longer describes the bytes it names is false as written, so
/// this is an ERROR rather than a warning. The remedy is small and specific:
/// either the artifact changed and the record must be regenerated, or the
/// artifact changed and should not have.
///
/// # Deliberately not silent about the missing case
///
/// A deliverable declaring `content_addressed` with no provenance, or with a
/// target that cannot be read, is reported rather than skipped. "The digest does
/// not match" and "there is nothing to match against" are different problems and
/// a check that collapsed them would send the reader to the wrong fix.
/// Does a signed record bind this Warrant's deliverable digests?
///
/// Exactly one thing does: a resolution, whose §56.2 record carries
/// `artifact_manifest_digest` = sha256 of `deliverables.toml`. Moving a pin
/// under it would change what the resolution resolved, so that is an ERROR and
/// `war correct` is the act for it (OW-WAR-0064).
///
/// An authorization does NOT. The contract digest covers intent, scope,
/// obligations, milestones and stages — not which bytes a file happens to have
/// while the work is being done. Treating it as binding sent a signed but
/// unresolved Warrant to `war correct`, which refuses with
/// `correction.not-resolved`: an error whose only remedy was itself refused.
///
/// So a pin that no one has resolved against is out of date, not violated —
/// `war pins --refresh` re-records it. That distinction is why `war check` can
/// run during ordinary work: a repository with nineteen unsigned Warrants
/// pinning living source files reported ten ERRORs and NOT READY on every
/// commit, forever, protecting nothing.
pub fn resolution_binds(repo: &Repository, one: &Loaded) -> bool {
    repo.load_resolution(&one.dir).ok().flatten().is_some()
}

fn check_deliverable_digests(
    repo: &Repository,
    one: &Loaded,
    alias: &str,
    ownership: &crate::ownership::Ownership,
    report: &mut Report,
) {
    let bound = resolution_binds(repo, one);
    let authorization = repo.load_authorization(&one.dir).ok().flatten();
    let authorized_at = authorization
        .as_ref()
        .and_then(|a| a.revision.authorization.as_ref())
        .map(|a| a.effective_time.clone());
    let deliverables = match repo.load_deliverables(&one.dir) {
        Ok(set) => set,
        Err(err) => {
            report.push(Diagnostic::error(
                "deliverable.unreadable",
                repo.relative(&one.dir.join("deliverables.toml")),
                format!("{alias}: {err}"),
            ));
            return;
        }
    };
    let file = repo.relative(&one.dir.join("deliverables.toml"));
    for (path, why) in &deliverables.failures {
        report.push(Diagnostic::error(
            "deliverable.malformed",
            path.clone(),
            format!("{why} — an unreadable deliverables file is not an absent one"),
        ));
    }

    // OW-ADR-0021: the set the authorizer signed for is the set that owns.
    // A record with no `owned` set predates ownership and owns nothing, so
    // there is nothing to compare; one with a set is held to it both ways.
    // `authorize` refuses a set that moved between drafting and signing
    // (`authorize.stale-deliverables`); these two catch the edit AFTER.
    if let Some(record) = &authorization
        && !record.owned.is_empty()
        && deliverables.failures.is_empty()
    {
        let declared: BTreeSet<(&str, &str)> = deliverables
            .records
            .iter()
            .map(|d| (d.id.as_str(), d.target_ref.as_str()))
            .collect();
        let owned: BTreeSet<(&str, &str)> = record
            .owned
            .iter()
            .map(|d| (d.id.as_str(), d.target_ref.as_str()))
            .collect();
        let mut agree = true;
        for (id, target) in declared.difference(&owned) {
            agree = false;
            report.push(Diagnostic::warn(
                "deliverable.undeclared-at-authorization",
                file.clone(),
                format!(
                    "{alias}: {id} → {target} is declared now but was not in the set the \
                     authorization signed for, so {alias} does not own it and no other \
                     Warrant's pin on it becomes historical. Ownership widens only through \
                     an amendment and a re-authorization (§31, OW-ADR-0021)"
                ),
            ));
        }
        for (id, target) in owned.difference(&declared) {
            agree = false;
            report.push(Diagnostic::error(
                "deliverable.declared-then-removed",
                file.clone(),
                format!(
                    "{alias}: the authorization signed for {id} → {target} and \
                     deliverables.toml no longer declares it. A signed claim on a path \
                     cannot be withdrawn by deleting the line — restore the declaration, \
                     or amend and re-authorize (§31, OW-ADR-0021)"
                ),
            ));
        }
        if agree {
            report.push(Diagnostic::pass(
                "deliverable.owned",
                format!(
                    "{alias}: the {} deliverable(s) declared are the {} the authorization \
                     signed for",
                    declared.len(),
                    owned.len()
                ),
            ));
        }
    }

    let addressed: Vec<_> = deliverables
        .records
        .iter()
        .filter(|d| d.content_addressed)
        .collect();
    if addressed.is_empty() {
        return;
    }

    // OW-WAR-0064 — a resolved Warrant's pin may have been superseded by an
    // authorized correction. The structural checks on the correction records
    // live in `correct::check`; the chain is resolved HERE, beside the digest
    // comparison, so "corrected" and "drifted" are decided by one computation.
    crate::correct::check(repo, one, alias, report);
    let corrections = repo.load_corrections(&one.dir).unwrap_or_default();

    let mut drifted = 0usize;
    let mut corrected = 0usize;
    let mut historical = 0usize;
    for deliverable in &addressed {
        let Some(provenance) = deliverable.provenance.as_ref() else {
            report.push(Diagnostic::error(
                "deliverable.no-provenance",
                file.clone(),
                format!(
                    "{alias}: {} declares content addressing and carries no provenance, so there \
                     is no digest to check",
                    deliverable.id
                ),
            ));
            drifted += 1;
            continue;
        };
        // Only sha256 is supported, and an unsupported algorithm is said so
        // rather than compared. `trim_start_matches` would leave "md5:abc"
        // intact, which never equals a sha256 hex, so the check still refuses —
        // but it refuses as "digest drift", sending the reader to regenerate a
        // record whose algorithm is the actual problem. The verdict was already
        // right; the diagnosis was not.
        let Some(recorded) = provenance.content_digest.strip_prefix("sha256:") else {
            report.push(Diagnostic::error(
                "deliverable.unsupported-digest",
                file.clone(),
                format!(
                    "{alias}: {} records {:?}, and only sha256: is supported. This is not                      drift — the record cannot be checked at all",
                    deliverable.id, provenance.content_digest
                ),
            ));
            drifted += 1;
            continue;
        };
        let (chain, head) =
            crate::correct::head_for(&corrections, &deliverable.id, &provenance.content_digest);
        let head = match head {
            Ok(h) => h,
            Err(openwarrant_core::correction::ChainError::Gap { expected, found }) => {
                report.push(Diagnostic::error(
                    "correction.sequence-gap",
                    file.clone(),
                    format!(
                        "{alias}: {} corrections are numbered 1..n without gaps; expected {expected}, \
                         found {found}",
                        deliverable.id
                    ),
                ));
                drifted += 1;
                continue;
            }
            Err(e @ openwarrant_core::correction::ChainError::SupersededNeverDelivered { .. }) => {
                report.push(Diagnostic::error(
                    "correction.superseded-never-delivered",
                    file.clone(),
                    format!("{alias}: {} — {e}", deliverable.id),
                ));
                drifted += 1;
                continue;
            }
        };
        let head_hex = head.trim_start_matches("sha256:");
        match std::fs::read(repo.root.join(&deliverable.target_ref)) {
            Ok(bytes) => {
                let actual = openwarrant_compiler::sha256_hex(&bytes);
                if actual == head_hex {
                    if !chain.is_empty() {
                        corrected += 1;
                        report.push(Diagnostic::pass(
                            "deliverable.corrected",
                            format!(
                                "{alias}: {} corrected {} time(s); sha256:{recorded} superseded, \
                                 now {head}",
                                deliverable.id,
                                chain.len()
                            ),
                        ));
                    }
                } else if let Some(newer) = bound
                    .then(|| {
                        ownership.newer_than(
                            &deliverable.target_ref,
                            alias,
                            authorized_at.as_deref(),
                        )
                    })
                    .flatten()
                {
                    // OW-ADR-0021: a later authorized Warrant declares this
                    // path, so the bytes are its to answer for. This pin is a
                    // claim about a moment — `war pins --history` finds the
                    // commit — and neither drift nor a correction applies.
                    // Decided before the correction branch on purpose: a
                    // chain that stopped matching because a NEWER OWNER moved
                    // the file is not a correction that corrects nothing.
                    historical += 1;
                    report.push(Diagnostic::pass(
                        "deliverable.superseded-by",
                        format!(
                            "{alias}: {} pinned {} at {head}; {}/{} (authorized {}) now \
                             governs that path, so this pin is historical and the bytes \
                             are that Warrant's to answer for (OW-ADR-0021) — `war pins \
                             --history {}`",
                            deliverable.id,
                            deliverable.target_ref,
                            newer.alias,
                            newer.deliverable_id,
                            newer.authorized_at,
                            deliverable.target_ref
                        ),
                    ));
                } else if !chain.is_empty() {
                    report.push(Diagnostic::error(
                        "correction.new-digest-mismatch",
                        file.clone(),
                        format!(
                            "{alias}: {} — the latest correction records {head} but the file is \
                             sha256:{actual}; it corrects nothing. A further change is a further \
                             correction, `war correct {alias} {}`",
                            deliverable.id, deliverable.id
                        ),
                    ));
                    drifted += 1;
                } else if bound {
                    report.push(Diagnostic::error(
                        "deliverable.digest-drift",
                        file.clone(),
                        format!(
                            "{alias}: {} records sha256:{recorded} for {} but the file is now \
                             sha256:{actual}. A resolution binds this manifest and no later \
                             authorized Warrant declares {}, so the artifact moved outside any \
                             authorization — restore it; declare it as a deliverable of a \
                             Warrant and have that Warrant authorized (OW-ADR-0021); or record \
                             why it moved: `war correct {alias} {}` (OW-WAR-0064)",
                            deliverable.id,
                            deliverable.target_ref,
                            deliverable.target_ref,
                            deliverable.id
                        ),
                    ));
                    drifted += 1;
                } else {
                    // Nobody has signed for this Warrant, so the pin is a note
                    // about a file, not a promise about it.
                    report.push(Diagnostic::warn(
                        "deliverable.pin-stale",
                        file.clone(),
                        format!(
                            "{alias}: {} records sha256:{recorded} for {} and the file is now \
                             sha256:{actual}. No resolution binds this manifest, so the pin is \
                             out of date rather than violated — `war pins --refresh {alias}`",
                            deliverable.id, deliverable.target_ref
                        ),
                    ));
                }
            }
            Err(err) => {
                let why = format!(
                    "{alias}: {} names {} and it cannot be read: {err}. An unreadable artifact \
                     is not a verified one",
                    deliverable.id, deliverable.target_ref
                );
                if bound {
                    report.push(Diagnostic::error(
                        "deliverable.target-unreadable",
                        file.clone(),
                        why,
                    ));
                    drifted += 1;
                } else {
                    report.push(Diagnostic::warn(
                        "deliverable.target-unreadable",
                        file.clone(),
                        why,
                    ));
                }
            }
        }
    }

    if drifted == 0 {
        report.push(Diagnostic::pass(
            "deliverable.digests",
            format!(
                "{alias}: {} content-addressed deliverable(s) match their bytes{}{}",
                addressed.len(),
                if corrected > 0 {
                    format!(" ({corrected} through an authorized correction)")
                } else {
                    String::new()
                },
                if historical > 0 {
                    format!(" ({historical} historical, governed by a later Warrant)")
                } else {
                    String::new()
                }
            ),
        ));
    }
}

/// §34 and §105 — the references a Warrant makes to the SAS and the Roadmap.
///
/// # Why these were never checked before
///
/// `Implements.contribution` is an `Option<String>` on disk and `RoadmapRef` is
/// a bare `String`, and both were copied verbatim into the IR. So a manifest
/// could say `contribution = "mostly"` or `roadmap://OW-PHASE-11/x` and nothing
/// would object — `war show` says outright that only `war://` is resolved. The
/// corpus projection groups Warrants by phase and derives requirement status
/// from contributions, so both now have to parse, and a value that does not
/// parse is reported here rather than silently dropped from a count.
///
/// An absent contribution is a warning, not an error: §34.2 says a WAR SHOULD
/// declare it, and turning a SHOULD into a refusal would be reading a rule into
/// the text.
fn check_traceability(
    repo: &Repository,
    one: &Loaded,
    alias: &str,
    roadmap: Option<&crate::roadmap_cmd::Loaded>,
    report: &mut Report,
) {
    use openwarrant_core::traceability::{Contribution, RequirementRef, RoadmapRef};

    let Some(basis) = one.basis.as_ref() else {
        return;
    };
    let file = repo.relative(&one.dir.join("manifest.toml"));
    let mut bad = 0usize;

    for r in &basis.manifest.roadmap {
        match RoadmapRef::parse(&r.r#ref) {
            Err(err) => {
                report.push(Diagnostic::error(
                    "roadmap.malformed",
                    file.clone(),
                    format!("{alias}: {err}"),
                ));
                bad += 1;
            }
            // A `roadmap://` ref names THIS program's §98: another prefix is a
            // phase of a SAS this repository does not carry (slice C5).
            Ok(parsed) if parsed.prefix != repo.config.project.namespace.as_str() => {
                report.push(Diagnostic::error(
                    "roadmap.wrong-namespace",
                    file.clone(),
                    format!(
                        "{alias}: {} names phase prefix {:?}; this repository's namespace is \
                         {:?}, and its SAS is the only §98 a roadmap ref can point into",
                        r.r#ref,
                        parsed.prefix,
                        repo.config.project.namespace.as_str()
                    ),
                ));
                bad += 1;
            }
            // OW-ADR-0023: with a roadmap record, the phase must be one of its
            // phases; without one, §98's 0..=10.
            Ok(parsed) => match roadmap {
                Some(rm) => {
                    if !crate::roadmap_cmd::check_ref(rm, alias, &parsed, &file, report) {
                        bad += 1;
                    }
                }
                None if parsed.phase > RoadmapRef::MAX_PHASE => {
                    report.push(Diagnostic::error(
                        "roadmap.malformed",
                        file.clone(),
                        format!(
                            "{alias}: {} names phase {}; §98 defines 0..=10 and this program has no roadmap record to say otherwise",
                            r.r#ref, parsed.phase
                        ),
                    ));
                    bad += 1;
                }
                None => {}
            },
        }
    }

    // §106 of the SAS as it stands: an `implements` ref must name a row that
    // exists. `None` when the document cannot be read — then nothing is
    // refused and nothing is vouched for (OW-WAR-0063).
    let known_requirements: Option<std::collections::BTreeMap<String, String>> = repo
        .sas_document()
        .ok()
        .map(|(_, bytes)| openwarrant_core::sas::section_106(&String::from_utf8_lossy(&bytes)))
        .filter(|m| !m.is_empty());
    for i in &basis.manifest.implements {
        if let Err(err) = RequirementRef::parse(&i.r#ref) {
            report.push(Diagnostic::error(
                "traceability.requirement-ref",
                file.clone(),
                format!("{alias}: {err}"),
            ));
            bad += 1;
        }
        if let Ok(rq) = RequirementRef::parse(&i.r#ref)
            && let Some(known) = &known_requirements
            && !known.contains_key(&rq.canonical())
        {
            bad += 1;
            report.push(Diagnostic::error(
                "traceability.unknown-requirement",
                repo.relative(&one.dir.join("manifest.toml")),
                format!(
                    "{alias}: implements {} and §106 of the pinned SAS has no such row (§34.1: a Warrant implements a requirement that exists)",
                    i.r#ref
                ),
            ));
        }
        match i.contribution.as_deref() {
            None => report.push(Diagnostic::warn(
                "traceability.contribution-unstated",
                file.clone(),
                format!(
                    "{alias}: {} declares no contribution; §34.2 says a WAR SHOULD state \
                     one of {}",
                    i.r#ref,
                    Contribution::known()
                ),
            )),
            Some(text) => {
                if let Err(err) = text.parse::<Contribution>() {
                    report.push(Diagnostic::error(
                        "traceability.contribution",
                        file.clone(),
                        format!("{alias}: {}: {err}", i.r#ref),
                    ));
                    bad += 1;
                }
            }
        }
    }

    if bad == 0 && !(basis.manifest.roadmap.is_empty() && basis.manifest.implements.is_empty()) {
        report.push(Diagnostic::pass(
            "traceability.refs",
            format!(
                "{alias}: {} requirement ref(s) and {} roadmap ref(s) parse",
                basis.manifest.implements.len(),
                basis.manifest.roadmap.len()
            ),
        ));
    }
}

/// What every Warrant's check reads from the corpus as a whole: built once
/// in `run`, never per Warrant.
#[derive(Clone, Copy)]
struct Shared<'a> {
    corpus: &'a [Loaded],
    /// Contract digests by alias, for a child's citation of its parent.
    parent_digests: &'a BTreeMap<String, String>,
    gates: &'a openwarrant_core::GateRegistry,
    /// OW-ADR-0021: which Warrant governs each path now.
    ownership: &'a crate::ownership::Ownership,
    /// OW-ADR-0023: the roadmap record, when the program has one.
    roadmap: Option<&'a crate::roadmap_cmd::Loaded>,
    /// OW-WAR-0125: recorded SAS revisions by section, for citations.
    sas_sections: &'a crate::sas::RevisionSections<'a>,
}

fn check_one(
    repo: &Repository,
    one: &Loaded,
    shared: Shared<'_>,
    check_generated: bool,
    report: &mut Report,
) {
    let Shared {
        corpus,
        parent_digests,
        gates,
        ownership,
        roadmap,
        sas_sections,
    } = shared;
    let alias = one.alias();

    // Carry forward whatever loading already found.
    for diagnostic in &one.report.diagnostics {
        report.push(diagnostic.clone());
    }

    let (Some(basis), Some(validated)) = (&one.basis, &one.validated) else {
        // The manifest was invalid; loading already reported why, and every
        // downstream check would be reporting consequences of that one fact.
        return;
    };

    report.push(Diagnostic::pass(
        "manifest.valid",
        format!("{alias}: manifest and composition are well-formed"),
    ));

    check_deliverable_digests(repo, one, &alias, ownership, report);
    check_traceability(repo, one, &alias, roadmap, report);
    {
        // §44.6 recorded runs and the §56.2 record, both held to the contract
        // as it compiles NOW (OW-WAR-0059).
        let current = match (&one.basis, &one.validated) {
            (Some(basis), Some(validated)) => openwarrant_compiler::lower(basis, validated)
                .ok()
                .and_then(|ir| ir.contract_digest().ok()),
            _ => None,
        };
        crate::evidence::check(repo, &one.dir, &alias, current.as_deref(), report);
        crate::resolution_cmd::check(repo, &one.dir, &alias, current.as_deref(), report);
        let uuid = one.validated.as_ref().map(|v| v.uuid.to_string());
        crate::journal_cmd::check(repo, &one.dir, &alias, uuid.as_deref(), report);
        // §14 — the SAS pin must name a recorded revision, and a Warrant pinned
        // behind the latest revision is said so. The pin is the latest
        // amendment's `sas_revision` when one names it (OW-ADR-0016), else the
        // authorization's.
        let all = repo.load_sas_revisions().unwrap_or_default();
        let amended = crate::repo::amendment_sas_revision(&one.dir);
        if let Some((v, amendment_path)) = &amended {
            let file = repo.relative(amendment_path);
            match all.iter().find(|r| &r.version == v) {
                None => report.push(Diagnostic::error(
                    "sas.pin-unknown",
                    file,
                    format!("{alias}: an amendment re-pins to SAS revision {v}, and no record of it exists under docs/sas/revisions/ — `war sas propose {v}` first"),
                )),
                Some(rev) => {
                    // The re-pinned revision must still carry every row this
                    // Warrant implements; a requirement that vanished under it
                    // is a broken trace, not a silent one.
                    for i in &basis.manifest.implements {
                        if let Ok(rq) = openwarrant_core::traceability::RequirementRef::parse(&i.r#ref)
                            && !rev.requirements.contains_key(&rq.canonical())
                        {
                            report.push(Diagnostic::error(
                                "sas.repin-unknown-requirement",
                                file.clone(),
                                format!("{alias}: re-pinned to SAS {v}, whose §106 has no {} — the Warrant implements a requirement that revision does not have", i.r#ref),
                            ));
                        }
                    }
                    if repo.load_resolution(&one.dir).ok().flatten().is_some() {
                        report.push(Diagnostic::warn(
                            "sas.repin-resolved",
                            file,
                            format!("{alias}: re-pinned to SAS {v} after resolution; the resolution binds the contract as it was and is reported stale, never moved (§56.3)"),
                        ));
                    }
                }
            }
        }
        // Is this authorization one a human signed? Until this call existed the
        // answer was "it says so in the file". A forged authorization.toml
        // naming the owner passed `war check` with zero errors and satisfied
        // §56.1 requirement 1 (demonstrated 2026-09-19 against 1.0.0-alpha.1).
        if let Ok(Some(a)) = repo.load_authorization(&one.dir)
            && let Some(auth) = &a.revision.authorization
        {
            {
                let verdict = crate::authority_check::verify(
                    repo,
                    crate::authority_check::Act::Authorize,
                    &alias,
                    &auth.authorizer,
                    Some(&a.revision.contract_digest),
                );
                let at = repo.relative(&one.dir.join("authorization.toml"));
                if verdict.is_signed() {
                    report.push(Diagnostic::pass(
                        verdict.rule(),
                        format!("{alias}: {}", verdict.why()),
                    ));
                } else {
                    report.push(Diagnostic::error(
                        verdict.rule(),
                        at,
                        format!("{alias}: {}", verdict.why()),
                    ));
                }
            }
            // OW-ADR-0029: an authorization made through a standing class is
            // re-derived, never trusted — the class, its signature, the stamp
            // against the class's expiry, count and revocation, and the
            // Warrant as it stands against every term. Removing this call
            // fails `conformance/plants.d/69-standing.sh`.
            crate::standing_cmd::check(repo, one, &a, report);
        }
        // A resolution is the act that says the work is done. It was trusted on
        // content alone for exactly as long as the authorization was.
        if let Ok(Some(r)) = repo.load_resolution(&one.dir) {
            let verdict = crate::authority_check::verify(
                repo,
                crate::authority_check::Act::Resolve,
                &alias,
                r.resolution.resolved_by_ref.trim_start_matches("person://"),
                Some(&r.resolution.contract_digest),
            );
            let at = repo.relative(&one.dir.join("resolution.toml"));
            if verdict.is_signed() {
                report.push(Diagnostic::pass(
                    "authority.signed",
                    format!("{alias} resolution: {}", verdict.why()),
                ));
            } else {
                report.push(Diagnostic::error(
                    verdict.rule(),
                    at,
                    format!("{alias} resolution: {}", verdict.why()),
                ));
            }
        }
        // Each correction moves a delivered file past the wall, so each needs
        // its own signature over its own bytes.
        if let Ok(set) = repo.load_corrections(&one.dir) {
            for (_, c) in &set.records {
                let subject = format!("{alias}.{}", c.correction.deliverable_id);
                let verdict = crate::authority_check::verify(
                    repo,
                    crate::authority_check::Act::Correct,
                    &subject,
                    c.correction
                        .authorized_by_ref
                        .trim_start_matches("person://"),
                    Some(&c.correction.new_digest),
                );
                if verdict.is_signed() {
                    report.push(Diagnostic::pass(
                        "authority.signed",
                        format!("{subject} correction: {}", verdict.why()),
                    ));
                } else {
                    report.push(Diagnostic::error(
                        verdict.rule(),
                        repo.relative(&one.dir.join("corrections")),
                        format!("{subject} correction: {}", verdict.why()),
                    ));
                }
            }
        }
        if let Ok(Some(a)) = repo.load_authorization(&one.dir)
            && let Some(v) = &a.sas_revision
            && amended.is_none()
        {
            if !all.iter().any(|r| &r.version == v) {
                report.push(Diagnostic::error(
                    "sas.pin-unknown",
                    repo.relative(&one.dir.join("authorization.toml")),
                    format!("{alias}: authorized against SAS revision {v}, and no record of it exists under docs/sas/revisions/"),
                ));
            } else if let Some(latest) = repo.latest_sas_revision().ok().flatten()
                && &latest.version != v
            {
                // A resolved Warrant executes nothing further under any
                // Basis; the revision it was accepted under is its history,
                // not a debt. Only a Warrant still open to execution is asked
                // to re-pin (OW-WAR-0112, OW-ADR-0021).
                if repo.load_resolution(&one.dir).ok().flatten().is_some() {
                    report.push(Diagnostic::pass(
                        "sas.pin-historical",
                        format!(
                            "{alias}: resolved under SAS {v}; {} is in force now and asks \
                             nothing of a Warrant that executes no further",
                            latest.version
                        ),
                    ));
                } else {
                    report.push(Diagnostic::warn(
                        "sas.pin-superseded",
                        repo.relative(&one.dir.join("authorization.toml")),
                        format!("{alias}: authorized against SAS {v}; the latest recorded revision is {} — the contract keeps its Basis until an amendment carrying `sas_revision: \"{}\"` re-pins it and a human re-authorizes (OW-ADR-0016)", latest.version, latest.version),
                    ));
                }
            }
        }
    }

    // Ordinals ascending is not required by the SAS, but a manifest whose
    // ordinals descend renders in an order its author probably did not intend.
    let ordinals: Vec<u32> = basis.manifest.atoms.iter().map(|a| a.ordinal).collect();
    let mut sorted = ordinals.clone();
    sorted.sort_unstable();
    if ordinals != sorted {
        report.push(Diagnostic::warn(
            "composition.ordinal-order",
            repo.relative(&one.dir.join("manifest.toml")),
            format!("{alias}: atom ordinals are not in ascending order; the parent renders in declared order"),
        ));
    }

    // §43 / RQ-056: a gate cited by an obligation must resolve to a registered,
    // bindable definition.
    //
    // OW-WAR-0019's Intent records why: in the parent project's corpus, 23 of 94
    // declared gates named a tool, script, or crate that was not in the tree.
    // Nothing read those strings, so nothing noticed.
    for atom in basis.atoms.iter().filter(|a| a.role == "assurance") {
        let text = String::from_utf8_lossy(&atom.bytes);
        let file = repo.relative(&one.dir.join(&atom.source));
        let cited = openwarrant_core::gate::cited_gate_uris(&text);
        let mut resolved = 0usize;
        for uri in &cited {
            match gates.resolve_citation(&alias, uri) {
                Ok(def) if def.lifecycle.is_bindable() => resolved += 1,
                Ok(def) => report.push(Diagnostic::error(

// SPDX-License-Identifier: Apache-2.0
//! `war next` — what should happen next in this repository, and whose act it
//! is.
//!
//! Two lists exist already: `war sign --list` (the human's acts) and the
//! corpus projection's `next_actionable` (stages an agent could execute).
//! Neither answers the question an agent asks first: "of everything pending,
//! which is MINE?" This merges them into one ordered list where every action
//! names its actor, and it is asserted over the whole table that no action
//! whose actor is `agent` is a signing act. An agent that reads this cannot be
//! told to authorize, resolve, accept or correct; it can only be told that a
//! human must, and how.
//!
//! t-67ed: ready ticket items come first. They are read from the ticket
//! store with the same computation `war ready` uses, carry `war claim`, and
//! are never a signature; the Warrant acts follow them, still judged.

use serde::Serialize;

use crate::repo::{RepoError, Repository};
use crate::sign::{self, Pending};

pub const SCHEMA: &str = "oh.war/next/v1";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Actor {
    Human,
    Agent,
}

/// What the act's dry run said about a signing command (OW-ADR-0022): the
/// ingest ran with the write withheld, and this is its verdict.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(tag = "verdict", rename_all = "snake_case")]
pub enum Judged {
    /// Every refusal passed; the signature is the only thing missing.
    WouldRecord,
    /// The ingest would refuse, and `rule` is the first rule that refused.
    WouldRefuse { rule: String },
}

impl Judged {
    #[must_use]
    pub fn word(&self) -> String {
        match self {
            Self::WouldRecord => "would record".to_owned(),
            Self::WouldRefuse { rule } => format!("would refuse: {rule}"),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct Action {
    pub actor: Actor,
    pub warrant: String,
    /// A short verb phrase: `authorize`, `resolve`, `correct`, `accept`,
    /// `check`, `deliver`, `verify`, `execute`.
    pub action: String,
    /// The command that does it, verbatim.
    pub command: String,
    pub why: String,
    /// On every action whose command begins `war sign`: the dry run's
    /// verdict on exactly that command. Absent on an agent's action, which
    /// has no signature to judge.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub judged: Option<Judged>,
}

/// A ticket item that can start now (`war ready`'s row), offered before any
/// Warrant act. Its command is always `war claim`: never a signature.
#[derive(Debug, Clone, Serialize)]
pub struct ReadyItem {
    pub actor: Actor,
    pub ticket: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub item: Option<String>,
    pub title: String,
    pub text: String,
    pub priority: u8,
    pub command: String,
}

impl ReadyItem {
    fn of(r: &crate::ticket::ReadyRow) -> Self {
        Self {
            actor: Actor::Agent,
            ticket: r.ticket.clone(),
            item: r.item.clone(),
            title: r.title.clone(),
            text: r.text.clone(),
            priority: r.priority,
            command: format!("war claim {}", r.target()),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct Next {
    pub schema: &'static str,
    /// Ticket items that can start now, most urgent first (t-67ed). Listed
    /// before `actions`; nothing here needs anyone's signature.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub ready: Vec<ReadyItem>,
    pub actions: Vec<Action>,
    /// Why `actions` is empty, when it is. Never silently empty.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub nothing: Option<String>,
    /// What stands in the way that no action here can clear (OW-WAR-0132):
    /// today `question.no-responder`, a blocking question nobody in the
    /// authority register may answer. UNKNOWN, never silently "waiting".
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub findings: Vec<Finding>,
}

/// A finding carried into `war next`, in the envelope diagnostic's shape.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Finding {
    pub rule: String,
    /// `unknown` / `warn` / `error`, as the envelope spells a severity.
    pub severity: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub file: Option<String>,
    pub message: String,
}

/// The pure part: given the pending human acts and the corpus projection,
/// derive the table. Separated from I/O so the "an agent never signs"
/// invariant can be asserted on synthetic inputs.
#[must_use]
pub fn derive(pending: &[Pending], status: &openwarrant_core::status::CorpusStatus) -> Next {
    let mut actions = Vec::new();
    // Human acts first: they unblock the most.
    for p in pending {
        let (warrant, action, target, why) = match p {
            Pending::Authorize {
                alias,
                revision,
                amendment,
                ..
            } => (
                alias.clone(),
                "authorize",
                alias.clone(),
                format!(
                    "revision {revision} awaits authorization{}",
                    amendment
                        .as_ref()
                        .map(|a| format!(" under {}", a.id))
                        .unwrap_or_default()
                ),
            ),
            Pending::Resolve { alias, request, .. } => (
                alias.clone(),
                "resolve",
                alias.clone(),
                if request.would_resolve_satisfied == Some(true) {
                    "the thirteen are met and §38.6 would resolve satisfied".to_owned()
                } else {
                    format!(
                        "the thirteen are met; {} obligation(s) unestablished, so the outcome must be named",
                        request.unestablished.len()
                    )
                },
            ),
            Pending::Accept { version, .. } => (
                format!("SAS {version}"),
                "accept",
                version.clone(),
                "a proposed SAS revision awaits acceptance".to_owned(),
            ),
            Pending::AcceptRoadmap { revision, request } => (
                "roadmap".to_owned(),
                "accept",
                "roadmap".to_owned(),
                format!(
                    "roadmap revision {revision} awaits acceptance: {}",
                    request.diff.summary()
                ),
            ),
            Pending::AcceptStanding { request } => (
                request.reference.clone(),
                "accept",
                crate::standing_cmd::target(&request.id, request.revision),
                format!(
                    "standing authorization {} awaits its one signature",
                    request.reference
                ),
            ),
            Pending::RevokeStanding { request } => (
                request.reference.clone(),
                "revoke",
                crate::standing_cmd::target(&request.id, request.revision),
                "a signed class, offered for revocation".to_owned(),
            ),
            Pending::Correct {
                alias,
                deliverable_id,
                request,
                ..
            } => (
                alias.clone(),
                "correct",
                format!("{alias}/{deliverable_id}"),
                format!("{} drifted after resolution", request.target_ref),
            ),
            Pending::Invalidate { gate, request } => (
                gate.clone(),
                "invalidate",
                gate.clone(),
                format!(
                    "invalidating {gate} would dispute {} resolution(s)",
                    request.disputes.len()
                ),
            ),
        };
        actions.push(Action {
            actor: Actor::Human,
            warrant,
            action: action.to_owned(),
            command: format!("war sign {target}"),
            why,
            judged: None,
        });
    }
    // Agent acts: whatever stands between a Warrant and the human's next act.
    for w in &status.warrants {
        use openwarrant_core::status::WarrantRung as R;
        let already_human = actions
            .iter()
            .any(|a| a.actor == Actor::Human && a.warrant == w.alias);
        match w.rung {
            R::Invalid => actions.push(Action {
                actor: Actor::Agent,
                warrant: w.alias.clone(),
                action: "check".to_owned(),
                command: format!("war check {}", w.alias),
                why: "the manifest does not validate".to_owned(),
                judged: None,
            }),
            // A pending human act on this Warrant is the unblocker; an agent
            // action beside it would be noise, so Draft is only an agent's when
            // no human act is pending.
            R::Draft if !already_human => {
                let unmet = w.unmet.join("; ");
                actions.push(Action {
                    actor: Actor::Agent,
                    warrant: w.alias.clone(),
                    action: "deliver".to_owned(),
                    command: format!("war evidence record {a} && war verify {a}", a = w.alias),
                    why: if unmet.is_empty() {
                        "not every §56.1 requirement is met".to_owned()
                    } else {
                        format!("unmet: {unmet}")
                    },
                    judged: None,
                });
            }
            R::ReadyToResolve if w.would_resolve_satisfied != Some(true) => {
                actions.push(Action {
                    actor: Actor::Agent,
                    warrant: w.alias.clone(),
                    action: "verify".to_owned(),
                    command: format!("war verify {}", w.alias),
                    why: "obligations remain unestablished; a blind verifier must dispose of them"
                        .to_owned(),
                    judged: None,
                });
            }
            _ => {}
        }
    }
    for s in &status.next_actionable {
        actions.push(Action {
            actor: Actor::Agent,
            warrant: s.warrant.clone(),
            action: "execute".to_owned(),
            command: format!("war dispatch {} {}", s.warrant, s.stage),
            why: format!("{} / {}: {}", s.milestone, s.stage, s.why),
            judged: None,
        });
    }
    // `assert!`, not `debug_assert!`: this invariant is the point of the
    // command and must hold in a release-built test binary too.
    assert!(
        actions
            .iter()
            .all(|a| a.actor != Actor::Agent || !a.command.starts_with("war sign")),
        "an agent is never handed a signing act"
    );
    let nothing = if actions.is_empty() {
        Some(
            status
                .nothing_actionable
                .as_ref()
                .map(|n| {
                    // `n.why` is already the sentence. Debug-printing the
                    // struct put `NothingActionable { objective: None,
                    // blocked_by: [], why: "..." }` on the terminal of anyone
                    // whose corpus had nothing to do — on the first command
                    // QUICKSTART tells a new reader to trust.
                    let mut s = n.why.clone();
                    if let Some(o) = &n.objective {
                        s.push_str(&format!(" ({o})"));
                    }
                    if !n.blocked_by.is_empty() {
                        s.push_str(&format!("; blocked by {}", n.blocked_by.join(", ")));
                    }
                    s
                })
                .unwrap_or_else(|| {
                    "nothing awaits a signature and no stage is actionable".to_owned()
                }),
        )
    } else {
        None
    };
    Next {
        schema: SCHEMA,
        ready: Vec::new(),
        actions,
        nothing,
        findings: Vec::new(),
    }
}

/// OW-WAR-0132: the frontier's question edge, applied to the table. A stage
/// a blocking question holds is not offered to an agent (`war dispatch` would
/// start work the question is meant to stop), and the frontier's
/// `question.no-responder` is carried as a finding. Pure over the frontier,
/// so the rule is testable without a repository.
pub fn apply_questions(
    next: &mut Next,
    frontier: &crate::frontier::Frontier,
    report: &crate::diagnostic::Report,
) {
    let held: std::collections::BTreeSet<(&str, &str)> = frontier
        .rows
        .iter()
        .filter(|r| {
            r.state == crate::frontier::StageState::Blocked
                && r.waiting_on.iter().any(|w| is_question(w))
        })
        .map(|r| (r.warrant.as_str(), r.stage.as_str()))
        .collect();
    next.actions.retain(|a| {
        a.action != "execute" || {
            let stage = a.command.rsplit(' ').next().unwrap_or_default();
            !held.contains(&(a.warrant.as_str(), stage))
        }
    });
    for d in &report.diagnostics {
        if d.rule == "question.no-responder" {
            next.findings.push(Finding {
                rule: d.rule.clone(),
                severity: d.severity.label().to_ascii_lowercase(),
                file: d.file.clone(),
                message: d.message.clone(),
            });
        }
    }
    if next.actions.is_empty() && next.nothing.is_none() {
        next.nothing = Some(if held.is_empty() {
            "nothing awaits a signature and no stage is actionable".to_owned()
        } else {
            format!(
                "every actionable stage waits on a blocking question: {}",
                held.iter()
                    .map(|(w, s)| format!("{w}/{s}"))
                    .collect::<Vec<_>>()
                    .join(", ")
            )
        });
    }
}

/// `Q-nnn`, as the frontier names a question in `waiting_on`; a milestone is
/// `M-…` / `MS-…` and never matches.
fn is_question(id: &str) -> bool {
    id.strip_prefix("Q-")
        .is_some_and(|n| !n.is_empty() && n.bytes().all(|b| b.is_ascii_digit()))
}

pub fn run(repo: &Repository) -> Result<Next, RepoError> {
    let status = crate::status::build(repo)?;
    run_with(repo, &status)
}

/// [`run`] over a corpus status already built, so a caller that also needs
/// the status (`war compile`'s master document) builds it once.
pub fn run_with(
    repo: &Repository,
    status: &openwarrant_core::status::CorpusStatus,
) -> Result<Next, RepoError> {
    let pending = sign::pending(repo)?;
    let mut next = derive(&pending, status);
    let (report, frontier) = crate::frontier::run(repo, None)?;
    apply_questions(&mut next, &frontier, &report);
    // OW-WAR-0141: a question waiting before its Warrant exists is a human's
    // act too (`answer`), read from `docs/intake/` by questions.rs.
    next.actions.extend(crate::questions::intake_actions(repo));
    if !next.actions.is_empty() {
        next.nothing = None;
    }
    judge(repo, &pending, &mut next);
    ready_tickets(repo, &mut next);
    Ok(next)
}

/// t-67ed: the ticket store's ready set, ahead of every Warrant act. The
/// same `ticket::ready_rows` `war ready` answers from, so the two never
/// disagree. A store that cannot be read is an UNKNOWN finding, never an
/// empty list presented as "nothing ready".
pub fn ready_tickets(repo: &Repository, next: &mut Next) {
    let rows = crate::ticket::Store::open(repo, None).and_then(|store| {
        let (tickets, _faults) = store.load_all()?;
        crate::ticket::ready_rows(&store, &tickets)
    });
    match rows {
        Ok(rows) => next.ready = rows.iter().map(ReadyItem::of).collect(),
        Err(e) => next.findings.push(Finding {
            rule: "next.tickets-unreadable".to_owned(),
            severity: "unknown".to_owned(),
            file: None,
            message: format!("the ticket store could not be read, so ready items are UNKNOWN: {e}"),
        }),
    }
}

/// The dry run in front of every handed-over command (OW-ADR-0022). The
/// whole queue is judged by one `war sign --all --dry-run` — each act
/// drafted, its ingest run with the write withheld — and each verdict is
/// carried beside the `war sign <target>` that act is. Acts the dry run would
/// refuse are listed after the ones it would record, so the first command a
/// human reads is one that will work. Writes nothing and holds no key: the
/// dry run's own guarantees (`sign::Options::dry_run`).
///
/// One sweep rather than one dry run per target: each `sign::run` re-reads
/// the whole queue, and a queue of a dozen acts judged one by one cost a
/// dozen reads of it. The sweep is over `pending` itself — the queue the
/// actions were derived from, read by the caller in this process — not a
/// second read of it (`sign::dry_run_all`, t-280c).
pub fn judge(repo: &Repository, pending: &[Pending], next: &mut Next) {
    let verdicts = match sign::dry_run_all(repo, pending) {
        Ok(report) => verdicts(pending, &report),
        Err(_) => std::collections::BTreeMap::new(),
    };
    for a in &mut next.actions {
        let Some(target) = a.command.strip_prefix("war sign ") else {
            continue;
        };
        let target = target.split_whitespace().next().unwrap_or(target);
        a.judged = Some(
            verdicts
                .get(target)
                .cloned()
                .unwrap_or_else(|| Judged::WouldRefuse {
                    rule: "sign.dry-run-failed".to_owned(),
                }),
        );
    }
    order(next);
}

/// The `war sign` target each pending act is handed over as — the same
/// words `derive` writes after `war sign `.
fn target_of(p: &Pending) -> String {
    match p {
        Pending::Authorize { alias, .. } | Pending::Resolve { alias, .. } => alias.clone(),
        Pending::Accept { version, .. } => version.clone(),
        Pending::AcceptRoadmap { .. } => "roadmap".to_owned(),
        Pending::Correct {
            alias,
            deliverable_id,
            ..
        } => format!("{alias}/{deliverable_id}"),
        Pending::Invalidate { gate, .. } => gate.clone(),
        Pending::AcceptStanding { .. } | Pending::RevokeStanding { .. } => {
            crate::sign::target_of(p)
        }
    }
}

/// Split a whole-queue dry run into one verdict per act. The sweep reports
/// each act as its ingest's diagnostics followed by one closing diagnostic
/// that names the act (`sign::line`): `sign.would-record`, or a refusal —
/// `sign.would-refuse`, `sign.who`, `sign.not-draftable`,
/// `sign.needs-decision`, `sign.dry-run-failed`.
fn verdicts(
    pending: &[Pending],
    report: &crate::diagnostic::Report,
) -> std::collections::BTreeMap<String, Judged> {
    const CLOSING: [&str; 6] = [
        "sign.would-record",
        "sign.would-refuse",
        "sign.who",
        "sign.not-draftable",
        "sign.needs-decision",
        "sign.dry-run-failed",
    ];
    let lines: Vec<(String, String)> = pending
        .iter()
        .map(|p| (sign::line(p), target_of(p)))
        .collect();
    let mut out = std::collections::BTreeMap::new();
    let mut segment = crate::diagnostic::Report::default();
    for d in &report.diagnostics {
        if !CLOSING.contains(&d.rule.as_str()) {
            segment.push(d.clone());
            continue;
        }
        let named = |l: &str| d.file.as_deref() == Some(l) || d.message.starts_with(l);
        if let Some((_, target)) = lines.iter().find(|(l, _)| named(l)) {
            segment.push(d.clone());
            out.insert(target.clone(), verdict(Ok(std::mem::take(&mut segment))));
        }
        segment = crate::diagnostic::Report::default();
    }
    out
}

/// Read a dry run's report as a verdict: `sign.would-record` is the only
/// recording word; otherwise the first error that is not the summary
/// `sign.would-refuse` names why.
fn verdict(report: Result<crate::diagnostic::Report, RepoError>) -> Judged {
    let report = match report {
        Ok(r) => r,
        Err(_) => {
            return Judged::WouldRefuse {
                rule: "sign.dry-run-failed".to_owned(),
            };
        }
    };
    if report
        .diagnostics
        .iter()
        .any(|d| d.rule == "sign.would-record")
    {
        return Judged::WouldRecord;
    }
    let rule = report
        .diagnostics
        .iter()
        .filter(|d| {
            d.severity == crate::diagnostic::Severity::Error || d.rule == "sign.needs-decision"
        })
        .map(|d| d.rule.clone())
        .find(|r| r != "sign.would-refuse")
        .unwrap_or_else(|| "sign.would-refuse".to_owned());
    Judged::WouldRefuse { rule }
}

/// Humans first; among them, what would record before what would refuse.
/// A stable sort, so the order within each group is `derive`'s.
fn order(next: &mut Next) {
    next.actions.sort_by_key(|a| match (a.actor, &a.judged) {
        (Actor::Human, Some(Judged::WouldRecord) | None) => 0,
        (Actor::Human, Some(Judged::WouldRefuse { .. })) => 1,
        (Actor::Agent, _) => 2,
    });
}

#[must_use]
pub fn render(n: &Next) -> String {
    let mut s = String::new();
    for r in &n.ready {
        s.push_str(&format!(
            "{:<6} {:<12} {:<10} {}\n{:>6} p{} {}{}\n",
            "ready",
            r.ticket,
            "claim",
            r.command,
            "",
            r.priority,
            r.text,
            if r.item.is_some() {
                format!(" — {}", r.title)
            } else {
                String::new()
            },
        ));
    }
    for a in &n.actions {
        s.push_str(&format!(
            "{:<6} {:<12} {:<10} {}{}\n{:>6} {}\n",
            match a.actor {
                Actor::Human => "HUMAN",
                Actor::Agent => "agent",
            },
            a.warrant,
            a.action,
            a.command,
            a.judged
                .as_ref()
                .map(|j| format!("  [{}]", j.word()))
                .unwrap_or_default(),
            "",
            a.why
        ));
    }
    if let Some(why) = &n.nothing {
        if n.ready.is_empty() {
            s.push_str(&format!("nothing to do: {why}\n"));
        } else {
            s.push_str(&format!("no Warrant act waits: {why}\n"));
        }
    }
    for f in &n.findings {
        s.push_str(&format!(
            "{} {}{}: {}\n",
            f.severity.to_ascii_uppercase(),
            f.rule,
            f.file
                .as_deref()
                .map(|p| format!(" ({p})"))
                .unwrap_or_default(),
            f.message
        ));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn row(
        stage: &str,
        state: crate::frontier::StageState,
        waiting: &[&str],
    ) -> crate::frontier::Row {
        crate::frontier::Row {
            warrant: "X-WAR-0001".to_owned(),
            stage: stage.to_owned(),
            title: String::new(),
            milestone: "MS-001".to_owned(),
            executor_kind: "agent".to_owned(),
            state,
            waiting_on: waiting.iter().map(|s| (*s).to_owned()).collect(),
        }
    }

    fn execute(stage: &str) -> Action {
        Action {
            actor: Actor::Agent,
            warrant: "X-WAR-0001".to_owned(),
            action: "execute".to_owned(),
            command: format!("war dispatch X-WAR-0001 {stage}"),
            why: String::new(),
            judged: None,
        }
    }

    #[test]
    fn a_question_held_stage_is_not_offered_and_no_responder_is_carried() {
        use crate::frontier::StageState::{Blocked, Open};
        let frontier = crate::frontier::Frontier {
            schema: crate::frontier::SCHEMA.to_owned(),
            rows: vec![
                row("STAGE-001", Blocked, &["Q-001"]),
                row("STAGE-002", Open, &[]),
                row("STAGE-003", Blocked, &["MS-000"]),
            ],
            open: 1,
            claimed: 0,
            done: 0,
            blocked: 2,
        };
        let mut report = crate::diagnostic::Report::default();
        report.push(crate::diagnostic::Diagnostic::unknown(
            "question.no-responder",
            "docs/authority/roles.toml".to_owned(),
            "nobody can answer",
        ));
        let mut next = Next {
            schema: SCHEMA,
            ready: Vec::new(),
            actions: vec![
                execute("STAGE-001"),
                execute("STAGE-002"),
                execute("STAGE-003"),
            ],
            nothing: None,
            findings: Vec::new(),
        };
        apply_questions(&mut next, &frontier, &report);
        let offered: Vec<&str> = next.actions.iter().map(|a| a.command.as_str()).collect();
        // The question-held stage is gone; a milestone wait is not this rule's.
        assert_eq!(
            offered,
            [
                "war dispatch X-WAR-0001 STAGE-002",
                "war dispatch X-WAR-0001 STAGE-003"
            ]
        );
        assert_eq!(next.findings.len(), 1);
        assert_eq!(next.findings[0].severity, "unknown");
        assert_eq!(
            next.findings[0].file.as_deref(),
            Some("docs/authority/roles.toml")
        );
        assert!(render(&next).contains("UNKNOWN question.no-responder"));

        // Refusal side: with only the held stage, the list says why it is
        // empty instead of going silent, and nothing is offered.
        let mut next = Next {
            schema: SCHEMA,
            ready: Vec::new(),
            actions: vec![execute("STAGE-001")],
            nothing: None,
            findings: Vec::new(),
        };
        apply_questions(&mut next, &frontier, &crate::diagnostic::Report::default());
        assert!(next.actions.is_empty());
        assert!(next.findings.is_empty());
        assert!(
            next.nothing
                .as_deref()
                .unwrap_or_default()
                .contains("X-WAR-0001/STAGE-001")
        );
    }

    #[test]
    fn an_agent_is_never_handed_a_signing_act_and_humans_come_first() {
        // The real corpus is the fixture: every kind of pending act exists in
        // it or in its history, and the invariant must hold over all of it.
        let root = camino::Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .canonicalize_utf8()
            .unwrap();
        let repo = Repository::open(root).unwrap();
        let n = run(&repo).unwrap();
        assert!(!n.actions.is_empty());
        for a in &n.actions {
            if a.actor == Actor::Agent {
                assert!(
                    !a.command.starts_with("war sign"),
                    "agent handed a signature: {a:?}"
                );
                assert!(
                    !["authorize", "resolve", "accept", "correct"].contains(&a.action.as_str())
                );
            } else {
                assert!(a.command.starts_with("war sign"), "{a:?}");
                assert!(
                    a.judged.is_some(),
                    "a signing command handed over unjudged: {a:?}"
                );
            }
        }
        // t-67ed: a ready ticket item is an agent's, and is a claim — never
        // a signature, never an authority verb.
        for r in &n.ready {
            assert_eq!(r.actor, Actor::Agent);
            assert!(r.command.starts_with("war claim "), "{r:?}");
            assert!(!r.command.contains("war sign"), "{r:?}");
        }
        let first_agent = n.actions.iter().position(|a| a.actor == Actor::Agent);
        let last_human = n.actions.iter().rposition(|a| a.actor == Actor::Human);
        if let (Some(fa), Some(lh)) = (first_agent, last_human) {
            assert!(lh < fa, "human acts are listed before agent acts");
        }
        let first_refused = n
            .actions
            .iter()
            .position(|a| matches!(a.judged, Some(Judged::WouldRefuse { .. })));
        let last_recordable = n
            .actions
            .iter()
            .rposition(|a| matches!(a.judged, Some(Judged::WouldRecord)));
        if let (Some(fr), Some(lr)) = (first_refused, last_recordable) {
            assert!(
                lr < fr,
                "a refusable act is listed after every recordable one"
            );
        }
    }

    #[test]
    fn a_verdict_names_the_ingest_rule_not_the_summary() {
        use crate::diagnostic::{Diagnostic, Report};
        let mut r = Report::default();
        r.push(Diagnostic::error("authorize.no-amendment", "x", "why"));
        r.push(Diagnostic::error("sign.would-refuse", "x", "summary"));
        assert_eq!(
            verdict(Ok(r)),
            Judged::WouldRefuse {
                rule: "authorize.no-amendment".into()
            }
        );
        let mut ok = Report::default();
        ok.push(Diagnostic::pass("sign.would-record", "fine"));
        assert_eq!(verdict(Ok(ok)), Judged::WouldRecord);
    }

    fn ready_item() -> ReadyItem {
        ReadyItem {
            actor: Actor::Agent,
            ticket: "t-0001".to_owned(),
            item: Some("i-0001".to_owned()),
            title: "A ticket".to_owned(),
            text: "The first item".to_owned(),
            priority: 1,
            command: "war claim t-0001/i-0001".to_owned(),
        }
    }

    fn human_act() -> Action {
        Action {
            actor: Actor::Human,
            warrant: "X-WAR-0001".to_owned(),
            action: "authorize".to_owned(),
            command: "war sign X-WAR-0001".to_owned(),
            why: "revision 1 awaits authorization".to_owned(),
            judged: Some(Judged::WouldRecord),
        }
    }

    #[test]
    fn a_ready_ticket_item_is_listed_before_a_human_act() {
        let next = Next {
            schema: SCHEMA,
            ready: vec![ready_item()],
            actions: vec![human_act()],
            nothing: None,
            findings: Vec::new(),
        };
        let out = render(&next);
        let claim = out
            .find("war claim t-0001/i-0001")
            .expect("the ready item is listed");
        let sign = out
            .find("war sign X-WAR-0001")
            .expect("the human act stays listed");
        assert!(claim < sign, "ready items come first:\n{out}");
        assert!(
            out.contains("[would record]"),
            "the human act is still judged"
        );
        // JSON: `ready` sits beside `actions`, and names an agent's claim.
        let v = serde_json::to_value(&next).unwrap();
        assert_eq!(v["ready"][0]["command"], "war claim t-0001/i-0001");
        assert_eq!(v["ready"][0]["actor"], "agent");
        assert_eq!(v["actions"][0]["actor"], "human");
    }

    #[test]
    fn with_no_ready_item_nothing_is_said_plainly_and_ready_is_omitted() {
        let next = Next {
            schema: SCHEMA,
            ready: Vec::new(),
            actions: Vec::new(),
            nothing: Some("nothing awaits".to_owned()),
            findings: Vec::new(),
        };
        assert!(render(&next).starts_with("nothing to do: nothing awaits"));
        let v = serde_json::to_value(&next).unwrap();
        assert!(v.get("ready").is_none());
        // Refusal side: with a ready item, "nothing to do" is not said.
        let next = Next {
            ready: vec![ready_item()],
            ..next
        };
        let out = render(&next);
        assert!(!out.contains("nothing to do"), "{out}");
        assert!(out.contains("no Warrant act waits: nothing awaits"));
    }
}

//! `war` with no arguments: the app (OW-WAR-0112, absorbing OW-WAR-0073).
//!
//! A rendering under SAS §76.6 and OW-ADR-0019/0020: it issues commands and
//! holds no key. Every act it starts shells out to the same `war sign
//! --ssh-sign` a hand would run, in a child that inherits the terminal, so
//! the `ssh-add -c` dialog remains the human act. Nothing under `tui/` names
//! `ssh-keygen` or `SSH_AUTH_SOCK`; the battery greps for both.
//!
//! # One answer per question
//!
//! Every pane reads the functions the CLI already answers with —
//! `console::board`, `next::run`, `status::build`, `frontier::run`,
//! `check::run`, `doctor::run`, `journal_cmd::load` — and renders. A pane
//! that computed a fact itself would be a second answer to a question the
//! records already answer, and the one nobody re-checks.
//!
//! # One file
//!
//! OW-WAR-0112's signed declaration names `tui/mod.rs` and nothing else under
//! `tui/`, so the app lives here in inner modules rather than in files the
//! authorization never saw. A later Warrant that declares `tui/*.rs` may
//! split it; this one may not widen its own set (OW-ADR-0021).
//!
//! # The terminal comes back
//!
//! Raw mode and the alternate screen are entered through one guard whose
//! `Drop` leaves them, and a panic hook leaves them before the default hook
//! prints — a library that takes the terminal owes it back on every exit
//! path. `--panic-after-setup` is the fixture the battery uses to prove it.
//!
//! # No executor
//!
//! Input is `crossterm::event::poll` on a 250 ms tick; nothing here is
//! async, so OW-ADR-0014's refusal stands untouched. Live refresh is
//! `watch.rs`'s fingerprint poller, consulted every fourth idle tick and
//! debounced one more, so a signature given in another terminal shows up
//! without a keypress.

use std::collections::BTreeMap;
use std::io::Write as _;
use std::time::Duration;

use camino::{Utf8Path, Utf8PathBuf};
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyEventKind, KeyModifiers};
use ratatui::Terminal;
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Clear, List, ListItem, ListState, Paragraph, Tabs, Wrap};

use crate::diagnostic::{Diagnostic, Report, Severity};
use crate::repo::{RepoError, Repository};

/// The refusal when there is no terminal: exit 2, by name, and not one
/// escape code on a pipe.
pub const NO_TTY: &str = "tui.no-tty";

/// `war` / `war tui`. Returns the exit code.
pub fn run(root: Option<Utf8PathBuf>, panic_after_setup: bool) -> Result<u8, RepoError> {
    if !crate::sign::at_a_terminal() {
        let mut report = Report::default();
        report.push(Diagnostic::error(
            NO_TTY,
            "-".to_owned(),
            "the app needs a terminal on stdin and stdout; for a script use `war status \
             --json`, `war console --json`, `war next --json` or `war check --json`",
        ));
        crate::check::print(&report);
        return Ok(crate::EXIT_NOT_READY);
    }
    let repo = Repository::discover(root.clone()).ok();
    // OW-WAR-0115: `war` where no repository is found opens the hub. Setup
    // for this directory stays one keypress away (`1`).
    let hub = repo.is_none() && root.is_none();
    let root = match (&repo, root) {
        (Some(r), _) => r.root.clone(),
        (None, Some(r)) => r,
        (None, None) => Utf8PathBuf::from_path_buf(
            std::env::current_dir().map_err(|e| RepoError::Message(e.to_string()))?,
        )
        .map_err(|_| RepoError::Message("the current directory is not UTF-8".to_owned()))?,
    };
    let mut model = Model::load(root, repo);
    if hub {
        model.pane = Pane::Projects;
        model.load_projects();
    }

    let guard = term::Guard::enter()?;
    // The hook runs before the default one prints the panic, so the message
    // lands on a restored screen rather than inside the alternate one.
    let default_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        term::leave_quietly();
        default_hook(info);
    }));
    if panic_after_setup {
        panic!("--panic-after-setup: the fixture that proves the terminal is restored");
    }
    let backend = CrosstermBackend::new(std::io::stdout());
    let mut terminal = Terminal::new(backend).map_err(io("could not open the terminal"))?;
    let result = event_loop(&mut terminal, &mut model);
    drop(guard);
    let _ = std::panic::take_hook();
    result.map(|()| crate::EXIT_OK)
}

fn io(context: &'static str) -> impl Fn(std::io::Error) -> RepoError {
    move |source| RepoError::Io {
        context: context.to_owned(),
        source,
    }
}

// ---------------------------------------------------------------------------
// The terminal guard
// ---------------------------------------------------------------------------

mod term {
    use super::io;
    use crate::repo::RepoError;
    use crossterm::terminal::{
        EnterAlternateScreen, LeaveAlternateScreen, disable_raw_mode, enable_raw_mode,
    };

    /// Raw mode and the alternate screen, both left on drop.
    pub struct Guard(());

    impl Guard {
        pub fn enter() -> Result<Self, RepoError> {
            enable_raw_mode().map_err(io("could not enter raw mode"))?;
            crossterm::execute!(std::io::stdout(), EnterAlternateScreen)
                .map_err(io("could not enter the alternate screen"))?;
            Ok(Self(()))
        }
    }

    impl Drop for Guard {
        fn drop(&mut self) {
            leave_quietly();
        }
    }

    /// Best effort, never failing: called from the panic hook and from drop.
    pub fn leave_quietly() {
        let _ = disable_raw_mode();
        let _ = crossterm::execute!(std::io::stdout(), LeaveAlternateScreen);
    }
}

// ---------------------------------------------------------------------------
// The model: read through the CLI's own functions, rendered and nothing else
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Pane {
    Setup,
    Help,
    Queue,
    Questions,
    Frontier,
    Corpus,
    Obligations,
    Evidence,
    Journal,
    Roadmap,
    Projects,
    Tickets,
}

impl Pane {
    const ALL: [Pane; 12] = [
        Pane::Setup,
        Pane::Help,
        Pane::Queue,
        Pane::Questions,
        Pane::Frontier,
        Pane::Corpus,
        Pane::Obligations,
        Pane::Evidence,
        Pane::Journal,
        Pane::Roadmap,
        Pane::Projects,
        Pane::Tickets,
    ];

    const fn title(self) -> &'static str {
        match self {
            Self::Setup => "1 Setup",
            Self::Help => "2 Help",
            Self::Queue => "3 Queue",
            Self::Questions => "4 Questions",
            Self::Frontier => "5 Frontier",
            Self::Corpus => "6 Corpus",
            Self::Obligations => "7 Obligations",
            Self::Evidence => "8 Evidence",
            Self::Journal => "9 Journal",
            Self::Roadmap => "0 Roadmap",
            Self::Projects => "p Projects",
            Self::Tickets => "t Tickets",
        }
    }
}

/// One row of any list pane: what is shown, the command behind it, and what
/// `Enter` or `v` does with it.
#[derive(Debug, Clone)]
struct Row {
    text: String,
    /// The exact command behind the row, for the bottom line.
    command: String,
    /// `war sign <target>`: the act `s`/`Enter` runs in a child.
    sign_target: Option<String>,
    /// A remedy `x` may run unasked.
    auto: Option<Vec<String>>,
    /// Detail `Enter` opens, when the row has more to say.
    detail: Option<String>,
}

/// One document the Help pane can show.
struct Doc {
    name: String,
    text: String,
}

struct Model {
    root: Utf8PathBuf,
    repo: Option<Repository>,
    program: String,
    sas_in_force: String,
    pane: Pane,
    /// Per pane: rows and the highlighted index.
    rows: BTreeMap<u8, Vec<Row>>,
    selected: BTreeMap<u8, usize>,
    /// Queue rows checked for a batch.
    checked: std::collections::BTreeSet<usize>,
    filter: String,
    filtering: bool,
    show_keys: bool,
    /// A popup with scrollable text (a request, a detail, a command's output).
    popup: Option<(String, String, u16)>,
    docs: Vec<Doc>,
    doc_index: usize,
    /// The Help pane's mode: what-next (false) or a document (true).
    reading: bool,
    status: String,
    setup: crate::init::guided::Machine,
    pending_count: usize,
    fingerprint: u64,
    fingerprint_pending: Option<u64>,
    idle_ticks: u32,
    /// The Projects pane's projects, index-aligned with its first rows;
    /// facts are read one project per idle tick (`tick_projects`).
    projects: Vec<crate::projects::Row>,
    /// Which project the next idle tick looks at.
    project_cursor: usize,
    /// `n` on Projects: the directory being typed for a new project.
    new_dir: Option<String>,
    /// The Help pane's first row: this binary, and PATH's `war` if it differs.
    binary: Row,
}

impl Model {
    fn load(root: Utf8PathBuf, repo: Option<Repository>) -> Self {
        let now = crate::gate_cmd::receipt::rfc3339_from_secs(
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map_or(0, |d| d.as_secs()),
        );
        let setup = crate::init::guided::Machine::new(crate::init::guided::Facts::read(&root), now);
        let mut m = Self {
            program: repo.as_ref().map_or_else(
                || root.file_name().unwrap_or("?").to_owned(),
                |r| r.config.project.name.clone(),
            ),
            sas_in_force: "none".to_owned(),
            pane: if setup.step == crate::init::guided::Step::Done {
                Pane::Queue
            } else {
                Pane::Setup
            },
            rows: BTreeMap::new(),
            selected: BTreeMap::new(),
            checked: std::collections::BTreeSet::new(),
            filter: String::new(),
            filtering: false,
            show_keys: false,
            popup: None,
            docs: Vec::new(),
            doc_index: 0,
            reading: false,
            status: String::new(),
            setup,
            pending_count: 0,
            fingerprint: 0,
            fingerprint_pending: None,
            idle_ticks: 0,
            projects: Vec::new(),
            project_cursor: 0,
            new_dir: None,
            binary: binary_row(),
            root,
            repo,
        };
        m.docs = m.load_docs();
        m.refresh();
        // t-67ed: the ticket loop is the default work path. A repository
        // with tickets opens on them; Setup and the Queue stay one key away.
        if m.rows
            .get(&(Pane::Tickets as u8))
            .is_some_and(|r| !r.is_empty())
        {
            m.pane = Pane::Tickets;
        }
        m
    }

    /// Everything the panes show, re-read. Never computes a fact of its own.
    fn refresh(&mut self) {
        self.setup
            .observe(crate::init::guided::Facts::read(&self.root));
        let Some(repo) = self.repo.as_ref() else {
            self.status = format!(
                "{} is not a repository — p lists your projects, 1 sets one up here",
                self.root
            );
            for p in Pane::ALL {
                self.rows.insert(p as u8, vec![]);
            }
            self.rows.insert(
                Pane::Setup as u8,
                vec![Row {
                    text: format!("→ {}", self.setup.step.title()),
                    command: "war init".to_owned(),
                    sign_target: None,
                    auto: None,
                    detail: Some(self.setup.question()),
                }],
            );
            self.rows
                .insert(Pane::Help as u8, self.help_rows(None, None, None));
            return;
        };
        let repo = repo.clone();
        self.sas_in_force = repo
            .latest_sas_revision()
            .ok()
            .flatten()
            .map_or_else(|| "none".to_owned(), |r| r.version);
        self.fingerprint = crate::watch::fingerprint(&watched(&repo));

        // The queue: `war sign --list`, through the console's board.
        let board = crate::console::board(&repo).ok();
        let mut queue = Vec::new();
        let mut questions = Vec::new();
        let mut stage_cmd: BTreeMap<(String, String), String> = BTreeMap::new();
        if let Some(b) = &board {
            for a in &b.acts {
                queue.push(Row {
                    text: format!("[{}] {}", a.n, a.line),
                    command: a.command.clone(),
                    sign_target: Some(a.target.clone()),
                    auto: None,
                    detail: None,
                });
            }
            for q in &b.questions {
                questions.push(Row {
                    text: format!(
                        "{} {}/{}: {}{}",
                        if q.blocking { "BLOCKING" } else { "        " },
                        q.warrant,
                        q.id,
                        q.question,
                        if q.recommended.is_empty() {
                            String::new()
                        } else {
                            format!("  → {}", q.recommended)
                        }
                    ),
                    command: q.command.clone(),
                    sign_target: None,
                    auto: None,
                    detail: Some(format!(
                        "{}\n\nrecommended: {}\n\n{}",
                        q.question, q.recommended, q.command
                    )),
                });
            }
            for s in &b.stages {
                stage_cmd.insert((s.warrant.clone(), s.stage.clone()), s.command.clone());
            }
        }
        self.pending_count = queue.len();
        self.checked.retain(|n| *n < queue.len());
        self.rows.insert(Pane::Queue as u8, queue);
        self.rows.insert(Pane::Questions as u8, questions);

        // The frontier.
        let mut frontier = Vec::new();
        if let Ok((_, f)) = crate::frontier::run(&repo, None) {
            for r in &f.rows {
                let cmd = stage_cmd
                    .get(&(r.warrant.clone(), r.stage.clone()))
                    .cloned()
                    .unwrap_or_else(|| format!("war frontier {}", r.warrant));
                frontier.push(Row {
                    text: format!(
                        "{:<8} {} {} — {} [{}]{}",
                        format!("{:?}", r.state).to_lowercase(),
                        r.warrant,
                        r.stage,
                        r.title,
                        r.executor_kind,
                        if r.waiting_on.is_empty() {
                            String::new()
                        } else {
                            format!("  waits on {}", r.waiting_on.join(", "))
                        }
                    ),
                    command: cmd,
                    sign_target: None,
                    auto: None,
                    detail: None,
                });
            }
        }
        self.rows.insert(Pane::Frontier as u8, frontier);

        // The corpus, obligations and evidence: one `status::build`.
        let status = crate::status::build(&repo).ok();
        let mut corpus = Vec::new();
        let mut obligations = Vec::new();
        let mut evidence = Vec::new();
        if let Some(s) = &status {
            for w in &s.warrants {
                let thirteen = w.checks.map_or_else(
                    || {
                        "the thirteen: not established (the Warrant could not be evaluated)"
                            .to_owned()
                    },
                    |c| {
                        c.as_pairs()
                            .iter()
                            .map(|(name, met)| format!("{} {name}", if *met { "✓" } else { "✗" }))
                            .collect::<Vec<_>>()
                            .join("\n")
                    },
                );
                corpus.push(Row {
                    text: format!(
                        "{:<16} {:<12} {}{}",
                        w.alias,
                        format!("{:?}", w.rung).to_lowercase(),
                        w.title.as_deref().unwrap_or(""),
                        if w.unmet.is_empty() {
                            String::new()
                        } else {
                            format!("  ({} unmet)", w.unmet.len())
                        }
                    ),
                    command: format!("war resolve {} --dry-run", w.alias),
                    sign_target: None,
                    auto: None,
                    detail: Some(format!(
                        "{} — {}\nrung: {:?}\n\n{thirteen}\n\nunestablished: {}\nblocking unknowns: {}",
                        w.alias,
                        w.title.as_deref().unwrap_or(""),
                        w.rung,
                        if w.unestablished.is_empty() { "none".to_owned() } else { w.unestablished.join(", ") },
                        if w.blocking_unknowns.is_empty() { "none".to_owned() } else { w.blocking_unknowns.join(", ") },
                    )),
                });
                for o in &w.obligations {
                    obligations.push(Row {
                        text: format!(
                            "{} {:<8} {:<14} {}{}",
                            w.alias,
                            o.id,
                            o.disposition,
                            o.verifier.as_deref().unwrap_or("no verifier"),
                            o.inadmissible_because
                                .as_deref()
                                .map_or(String::new(), |why| format!("  inadmissible: {why}")),
                        ),
                        command: format!("war resolve {} --dry-run", w.alias),
                        sign_target: None,
                        auto: None,
                        detail: Some(format!(
                            "{} {}\n\n{}\n\nscope: {}\ngate: {}\ndisposition: {}\nverifier: {} ({})\n{}",
                            w.alias,
                            o.id,
                            o.statement,
                            o.scope,
                            o.gate.as_deref().unwrap_or("none"),
                            o.disposition,
                            o.verifier.as_deref().unwrap_or("none"),
                            o.verifier_kind.as_deref().unwrap_or("-"),
                            o.inadmissible_because
                                .as_deref()
                                .map_or(String::new(), |w| format!("inadmissible because: {w}")),
                        )),
                    });
                }
                for g in &w.gate_runs {
                    evidence.push(Row {
                        text: format!(
                            "{:<12} {} {} {} {}{}",
                            g.class,
                            w.alias,
                            g.gate,
                            g.run_id,
                            g.verdict,
                            g.why.as_deref().map_or(String::new(), |y| format!("  {y}")),
                        ),
                        command: format!("war evidence record {} --gate {}", w.alias, g.gate),
                        sign_target: None,
                        auto: Some(vec![
                            "war".to_owned(),
                            "evidence".to_owned(),
                            "record".to_owned(),
                            w.alias.clone(),
                            "--gate".to_owned(),
                            g.gate.clone(),
                        ]),
                        detail: g.receipt_ref.as_ref().map(|r| format!("receipt: {r}")),
                    });
                }
            }
        }
        evidence.sort_by(|a, b| a.text.cmp(&b.text));
        self.rows.insert(Pane::Corpus as u8, corpus);
        self.rows.insert(Pane::Obligations as u8, obligations);
        self.rows.insert(Pane::Evidence as u8, evidence);

        // The journal: every Warrant's events, newest first.
        let mut journal = Vec::new();
        if let Ok(dirs) = repo.warrant_dirs() {
            for dir in dirs {
                let alias = dir.file_name().unwrap_or("?").to_owned();
                match crate::journal_cmd::load(&dir) {
                    Ok(j) => {
                        for e in &j.events {
                            journal.push(Row {
                                text: format!(
                                    "{} {:<14} {:<28} {}",
                                    e.occurred_at, alias, e.event_type, e.actor_ref
                                ),
                                command: format!("war journal {alias}"),
                                sign_target: None,
                                auto: None,
                                detail: Some(format!(
                                    "{}\n{}\n\n{}",
                                    e.occurred_at, e.event_type, e.payload
                                )),
                            });
                        }
                    }
                    Err(e) => journal.push(Row {
                        text: format!("UNREADABLE {alias}: {e}"),
                        command: format!("war journal {alias}"),
                        sign_target: None,
                        auto: None,
                        detail: None,
                    }),
                }
            }
        }
        journal.sort_by(|a, b| b.text.cmp(&a.text));
        self.rows.insert(Pane::Journal as u8, journal);

        // The roadmap: phases in dependency order, from `war roadmap`'s view.
        let mut roadmap = Vec::new();
        match crate::roadmap_cmd::view(&repo) {
            Ok((_, v)) => {
                for p in &v.phases {
                    roadmap.push(Row {
                        text: format!(
                            "{:<12} {:<34} {:>3} Warrant(s)  {}{}",
                            p.id,
                            p.title,
                            p.members.len(),
                            p.achieved,
                            if p.open.is_empty() {
                                String::new()
                            } else {
                                format!("  · no Warrant yet: {}", p.open.join(", "))
                            }
                        ),
                        command: "war roadmap edit".to_owned(),
                        sign_target: None,
                        auto: None,
                        detail: Some(format!(
                            "{} — {}\n\nexit: {}\nafter: {}\ntier: {}\nmembers: {}",
                            p.id,
                            p.title,
                            p.exit,
                            if p.depends_on.is_empty() {
                                "nothing".to_owned()
                            } else {
                                p.depends_on.join(", ")
                            },
                            p.tier.as_deref().unwrap_or("-"),
                            p.members.join(", ")
                        )),
                    });
                }
                if !v.accepted {
                    roadmap.insert(
                        0,
                        Row {
                            text: match v.pending_revision {
                                Some(n) => {
                                    format!("HUMAN  roadmap revision {n} awaits one signature")
                                }
                                None => "WARN   the roadmap atoms are not an accepted revision"
                                    .to_owned(),
                            },
                            command: "war sign roadmap --ssh-sign".to_owned(),
                            sign_target: v.pending_revision.map(|_| "roadmap".to_owned()),
                            auto: None,
                            detail: None,
                        },
                    );
                }
            }
            Err(e) => roadmap.push(Row {
                text: format!("no roadmap record: {e}"),
                command: "war roadmap".to_owned(),
                sign_target: None,
                auto: None,
                detail: None,
            }),
        }
        self.rows.insert(Pane::Roadmap as u8, roadmap);

        // Tickets (t-67ed): `ticket::board`, the same answer `war tickets`,
        // `war show` and `war ready` give. Read-only: no row signs or runs.
        let tickets = crate::ticket::Store::open(&repo, None)
            .and_then(|store| crate::ticket::board(&store))
            .map_or_else(
                |e| {
                    vec![Row {
                        text: format!("UNKNOWN: the tickets could not be read: {e}"),
                        command: "war tickets".to_owned(),
                        sign_target: None,
                        auto: None,
                        detail: None,
                    }]
                },
                |b| ticket_rows(&b),
            );
        self.rows.insert(Pane::Tickets as u8, tickets);

        // Setup and Help.
        self.rows.insert(
            Pane::Setup as u8,
            vec![Row {
                text: format!("→ {}", self.setup.step.title()),
                command: "war init".to_owned(),
                sign_target: None,
                auto: None,
                detail: Some(self.setup.question()),
            }],
        );
        let next = crate::next::run(&repo).ok();
        let (doctor, _) = crate::doctor::run(Some(self.root.clone()), None, false);
        let check = crate::check::run(&repo, None, false).ok();
        self.rows.insert(
            Pane::Help as u8,
            self.help_rows(next.as_ref(), Some(&doctor), check.as_ref()),
        );

        for p in Pane::ALL {
            let n = self.rows.get(&(p as u8)).map_or(0, Vec::len);
            let sel = self.selected.entry(p as u8).or_insert(0);
            if *sel >= n {
                *sel = n.saturating_sub(1);
            }
        }
        self.status = format!(
            "{} · {} · SAS {} · {} act(s) awaiting a signature · p projects",
            self.program, self.root, self.sas_in_force, self.pending_count
        );
    }

    /// What next: the Setup step if incomplete, then `war next`'s actions
    /// (human first), then doctor's non-passes, then `war check`'s errors
    /// deduped by rule with counts — each with its remedy.
    fn help_rows(
        &self,
        next: Option<&crate::next::Next>,
        doctor: Option<&Report>,
        check: Option<&Report>,
    ) -> Vec<Row> {
        let mut rows = vec![self.binary.clone()];
        if self.setup.step != crate::init::guided::Step::Done {
            rows.push(Row {
                text: format!(
                    "setup: {} — press Enter on the Setup tab",
                    self.setup.step.title()
                ),
                command: "war init".to_owned(),
                sign_target: None,
                auto: None,
                detail: Some(self.setup.question()),
            });
        }
        if let Some(n) = next {
            // t-67ed: ready ticket items first, as `war next` lists them.
            // Shown, never run from here: no auto, no signature.
            for r in &n.ready {
                rows.push(Row {
                    text: format!("ready claim      {} — {}", r.ticket, r.text),
                    command: r.command.clone(),
                    sign_target: None,
                    auto: None,
                    detail: None,
                });
            }
            for a in &n.actions {
                rows.push(Row {
                    // A signing command arrives judged by its dry run
                    // (OW-ADR-0022); the verdict sits beside it, so a human
                    // reads `would refuse: <rule>` before pressing Enter.
                    text: format!(
                        "{:<5} {:<10} {} — {}{}",
                        match a.actor {
                            crate::next::Actor::Human => "HUMAN",
                            crate::next::Actor::Agent => "agent",
                        },
                        a.action,
                        a.warrant,
                        a.why,
                        a.judged
                            .as_ref()
                            .map(|j| format!(" [{}]", j.word()))
                            .unwrap_or_default()
                    ),
                    sign_target: a
                        .command
                        .strip_prefix("war sign ")
                        .map(|t| t.split_whitespace().next().unwrap_or(t).to_owned()),
                    auto: (a.actor == crate::next::Actor::Agent
                        && !a.command.starts_with("war sign"))
                    .then(|| a.command.split_whitespace().map(str::to_owned).collect()),
                    command: a.command.clone(),
                    detail: None,
                });
            }
            if let Some(why) = &n.nothing {
                rows.push(Row {
                    text: if n.ready.is_empty() {
                        format!("nothing to do: {why}")
                    } else {
                        format!("no Warrant act waits: {why}")
                    },
                    command: "war next".to_owned(),
                    sign_target: None,
                    auto: None,
                    detail: None,
                });
            }
        }
        if let Some(d) = doctor {
            for diag in d
                .diagnostics
                .iter()
                .filter(|d| d.severity != Severity::Pass)
            {
                rows.push(remedy_row(diag, 1));
            }
        }
        if let Some(c) = check {
            let mut by_rule: BTreeMap<&str, (usize, &Diagnostic)> = BTreeMap::new();
            for diag in c
                .diagnostics
                .iter()
                .filter(|d| d.severity == Severity::Error)
            {
                by_rule
                    .entry(&diag.rule)
                    .and_modify(|e| e.0 += 1)
                    .or_insert((1, diag));
            }
            for (_, (n, diag)) in by_rule {
                rows.push(remedy_row(diag, n));
            }
        }
        if rows.len() == 1 {
            rows.push(Row {
                text: "nothing pending, nothing red — `war next` agrees".to_owned(),
                command: "war next".to_owned(),
                sign_target: None,
                auto: None,
                detail: None,
            });
        }
        rows
    }

    /// The documents Help can show: shipped ones embedded at build time (so
    /// help never drifts from what `war init` ships), this repository's own
    /// first when present.
    fn load_docs(&self) -> Vec<Doc> {
        let mut docs = Vec::new();
        // The master document first (OW-ADR-0022): what is authoritative
        // here now, generated by `war compile`. Read from disk, because it is
        // this repository's; a program that has not compiled has none.
        if let Ok(text) =
            std::fs::read_to_string(self.root.join(openwarrant_compiler::current::CURRENT_PATH))
        {
            docs.push(Doc {
                name: format!(
                    "this repository: {}",
                    openwarrant_compiler::current::CURRENT_PATH
                ),
                text,
            });
        }
        for name in ["AGENTS.md", "CONTEXT.md", "CONTRIBUTING.md"] {
            if let Ok(text) = std::fs::read_to_string(self.root.join(name)) {
                docs.push(Doc {
                    name: format!("this repository: {name}"),
                    text,
                });
            }
        }
        let ns = self
            .repo
            .as_ref()
            .map_or("OW", |r| r.config.project.namespace.as_str())
            .to_owned();
        for (name, text) in [
            (
                "docs/TUI.md",
                include_str!("../../../../docs/TUI.md").to_owned(),
            ),
            (
                "QUICKSTART.md",
                include_str!("../../../../QUICKSTART.md").to_owned(),
            ),
            (
                "README.md",
                include_str!("../../../../README.md").to_owned(),
            ),
            (
                "docs/DEFINITIONS.md",
                include_str!("../../../../docs/DEFINITIONS.md").to_owned(),
            ),
            (
                "docs/SKILLS.md",
                include_str!("../../../../docs/SKILLS.md").to_owned(),
            ),
            (
                "AGENTS.md (as `war init` ships it)",
                crate::init::render_agents_md(&ns),
            ),
        ] {
            docs.push(Doc {
                name: name.to_owned(),
                text,
            });
        }
        docs
    }

    fn rows(&self) -> &[Row] {
        self.rows.get(&(self.pane as u8)).map_or(&[], Vec::as_slice)
    }

    /// The rows the filter keeps, with their original indices.
    fn visible(&self) -> Vec<(usize, &Row)> {
        let f = self.filter.to_lowercase();
        self.rows()
            .iter()
            .enumerate()
            .filter(|(_, r)| f.is_empty() || r.text.to_lowercase().contains(&f))
            .collect()
    }

    fn selected(&self) -> usize {
        self.selected.get(&(self.pane as u8)).copied().unwrap_or(0)
    }

    fn select(&mut self, i: usize) {
        self.selected.insert(self.pane as u8, i);
    }

    fn current(&self) -> Option<&Row> {
        let v = self.visible();
        v.get(self.selected()).map(|(_, r)| *r)
    }

    fn current_index(&self) -> Option<usize> {
        let v = self.visible();
        v.get(self.selected()).map(|(i, _)| *i)
    }

    /// The Projects pane: every project named at once, from the list alone;
    /// each one's facts arrive on later idle ticks (OW-WAR-0115's basis: at
    /// most one project read per tick, re-read only when its fingerprint
    /// moves), so a long list never stalls the app.
    fn load_projects(&mut self) {
        self.projects = crate::projects::listed();
        self.project_cursor = 0;
        if self.projects.is_empty() {
            self.status =
                "no projects yet: run any `war` command inside a repository and it is remembered"
                    .to_owned();
        }
        self.render_projects();
        self.selected.insert(Pane::Projects as u8, 0);
    }

    /// One idle tick's worth: the first project not yet read, or else the
    /// next one round-robin, re-read only if its fingerprint moved.
    fn tick_projects(&mut self) {
        let n = self.projects.len();
        if n == 0 {
            return;
        }
        let i = self
            .projects
            .iter()
            .position(|r| !r.missing && r.fingerprint.is_none() && r.unreadable.is_none())
            .unwrap_or_else(|| {
                self.project_cursor = (self.project_cursor + 1) % n;
                self.project_cursor
            });
        let row = &mut self.projects[i];
        if row.missing {
            return;
        }
        if row.fingerprint.is_some() && crate::projects::fingerprint(&row.root) == row.fingerprint {
            return;
        }
        crate::projects::read_facts(row);
        if row.fingerprint.is_none() {
            // Unreadable: keep the reason and stop retrying it every tick.
            row.fingerprint = Some(0);
        }
        self.render_projects();
    }

    fn render_projects(&mut self) {
        let mut rows = Vec::new();
        for r in &self.projects {
            let facts = if r.missing {
                "(missing)".to_owned()
            } else if r.fingerprint.is_none() {
                "reading…".to_owned()
            } else {
                crate::projects::summary(r)
            };
            rows.push(Row {
                text: format!(
                    "{:<26} {}  {facts}",
                    r.program.as_deref().unwrap_or("?"),
                    r.root
                ),
                command: format!("war --root {}", r.root),
                sign_target: None,
                auto: None,
                detail: Some(if r.missing {
                    format!(
                        "{} holds no openwarrant.toml any more.\n\n`war projects --forget {}` removes it from the list.",
                        r.root, r.root
                    )
                } else {
                    format!("{}\n\n{facts}", r.root)
                }),
            });
        }
        for (text, command, detail) in [
            (
                "+ a new project in another directory (n)".to_owned(),
                "war init --root <directory>".to_owned(),
                "`n` asks for a directory, creates it if needed, and runs `war init` there.",
            ),
            (
                format!("+ set up {} (1)", self.root),
                "war init".to_owned(),
                "The Setup pane runs `war init` in this directory.",
            ),
        ] {
            rows.push(Row {
                text,
                command,
                sign_target: None,
                auto: None,
                detail: Some(detail.to_owned()),
            });
        }
        self.rows.insert(Pane::Projects as u8, rows);
    }

    /// Switch the whole app to another project: a fresh model, as if `war`
    /// had been started there — nothing of this one carries over.
    fn open_project(&mut self, root: Utf8PathBuf) {
        let repo = Repository::discover(Some(root.clone())).ok();
        if let Some(r) = &repo {
            crate::projects::touch(&r.root);
        }
        let opened = repo.is_some();
        *self = Model::load(root, repo);
        if !opened {
            self.pane = Pane::Setup;
        }
    }
}

/// This binary's identity and path, and a warning when `war` on PATH is a
/// different build — the 2026-09-23 failure, where a command handed over
/// ran an older `war` than the one that drafted it.
///
/// OW-WAR-0143: the comparison is the whole `--version` line, not its last
/// word. Two builds of one version (a release and a checkout 62 commits past
/// it) share the version and differ in the line; only the line tells them
/// apart. The remedy is `install::remedy`, the command for this install.
fn binary_row() -> Row {
    let here = crate::build_identity::version_line();
    let exe = std::env::current_exe()
        .ok()
        .and_then(|p| p.canonicalize().ok())
        .map_or_else(|| "?".to_owned(), |p| p.display().to_string());
    let on_path = std::env::var_os("PATH").and_then(|paths| {
        std::env::split_paths(&paths)
            .map(|d| d.join("war"))
            .find(|p| p.is_file())
    });
    let install = crate::install::remedy(env!("CARGO_PKG_VERSION"));
    let (text, detail) = match on_path {
        None => (
            format!("INFO    this is {here} at {exe}; no `war` on PATH"),
            format!("Commands this app hands over say `war`. To put one on PATH: `{install}`."),
        ),
        Some(p) => {
            let canonical = p
                .canonicalize()
                .map_or_else(|_| p.display().to_string(), |c| c.display().to_string());
            let version = std::process::Command::new(&p)
                .arg("--version")
                .output()
                .ok()
                .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_owned())
                .unwrap_or_default();
            if canonical == exe || version == here {
                (
                    format!("INFO    {here} at {exe} — the `war` on PATH"),
                    format!("`war` on PATH is {canonical}, the same build."),
                )
            } else {
                (
                    format!(
                        "WARN    this is {here} at {exe}; `war` on PATH is {} at {canonical}",
                        if version.is_empty() {
                            "unknown".to_owned()
                        } else {
                            version.clone()
                        }
                    ),
                    format!(
                        "A command you copy from here and run as `war` runs {canonical} ({version}), not this {here}. \
                         Update it: `{install}`, or run this one by path: {exe}."
                    ),
                )
            }
        }
    };
    Row {
        text,
        command: install,
        sign_target: None,
        auto: None,
        detail: Some(detail),
    }
}

fn remedy_row(diag: &Diagnostic, n: usize) -> Row {
    let remedy = crate::remedy::remedy_for(diag);
    let command = remedy.as_ref().map_or_else(
        || format!("war check  # {}", diag.rule),
        crate::remedy::Remedy::command,
    );
    Row {
        text: format!(
            "{:<7} {:<34} ×{n}  {}",
            diag.severity.label(),
            diag.rule,
            remedy
                .as_ref()
                .map_or("no remedy on record", |r| r.purpose.as_str())
        ),
        sign_target: remedy
            .as_ref()
            .filter(|r| {
                r.kind == crate::remedy::Kind::Human
                    && r.argv.first().is_some_and(|a| a == "war")
                    && r.argv.get(1).is_some_and(|a| a == "sign")
            })
            .and_then(|r| r.argv.get(2).cloned()),
        auto: remedy
            .as_ref()
            .filter(|r| r.kind == crate::remedy::Kind::Auto)
            .map(|r| r.argv.clone()),
        detail: Some(format!("{}\n\n{}\n\n{}", diag.rule, diag.message, command)),
        command,
    }
}

// ---------------------------------------------------------------------------
// The event loop
// ---------------------------------------------------------------------------

fn event_loop(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    m: &mut Model,
) -> Result<(), RepoError> {
    loop {
        terminal
            .draw(|f| draw(f, m))
            .map_err(io("could not draw"))?;
        if event::poll(Duration::from_millis(250)).map_err(io("could not poll the terminal"))? {
            match event::read().map_err(io("could not read the terminal"))? {
                Event::Key(k) if k.kind == KeyEventKind::Press => {
                    if handle_key(terminal, m, k)? == Flow::Quit {
                        return Ok(());
                    }
                }
                Event::Resize(..) => {}
                _ => {}
            }
            m.idle_ticks = 0;
            continue;
        }
        // Idle: every fourth tick look at the tree; a change is applied on
        // the tick after it settles (debounced one more).
        m.idle_ticks = m.idle_ticks.wrapping_add(1);
        if m.pane == Pane::Projects {
            m.tick_projects();
        }
        if m.idle_ticks.is_multiple_of(4)
            && let Some(repo) = m.repo.as_ref()
        {
            let fp = crate::watch::fingerprint(&watched(repo));
            match m.fingerprint_pending {
                Some(p) if p == fp && fp != m.fingerprint => {
                    m.fingerprint_pending = None;
                    m.refresh();
                }
                _ if fp != m.fingerprint => m.fingerprint_pending = Some(fp),
                _ => m.fingerprint_pending = None,
            }
        }
    }
}

#[derive(PartialEq, Eq)]
enum Flow {
    Continue,
    Quit,
}

fn handle_key(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    m: &mut Model,
    k: KeyEvent,
) -> Result<Flow, RepoError> {
    // A popup takes every key until it is closed.
    if let Some((_, _, scroll)) = m.popup.as_mut() {
        match k.code {
            KeyCode::Esc | KeyCode::Char('q') | KeyCode::Enter => m.popup = None,
            KeyCode::Char('j') | KeyCode::Down => *scroll = scroll.saturating_add(1),
            KeyCode::Char('k') | KeyCode::Up => *scroll = scroll.saturating_sub(1),
            KeyCode::PageDown => *scroll = scroll.saturating_add(20),
            KeyCode::PageUp => *scroll = scroll.saturating_sub(20),
            _ => {}
        }
        return Ok(Flow::Continue);
    }
    if m.filtering {
        match k.code {
            KeyCode::Esc => {
                m.filter.clear();
                m.filtering = false;
            }
            KeyCode::Enter => m.filtering = false,
            KeyCode::Backspace => {
                m.filter.pop();
            }
            KeyCode::Char(c) => m.filter.push(c),
            _ => {}
        }
        m.select(0);
        return Ok(Flow::Continue);
    }
    if m.show_keys {
        m.show_keys = false;
        return Ok(Flow::Continue);
    }
    // `n` on Projects: a directory is being typed.
    if let Some(buf) = m.new_dir.as_mut() {
        match k.code {
            KeyCode::Esc => m.new_dir = None,
            KeyCode::Backspace => {
                buf.pop();
            }
            KeyCode::Char(c) => buf.push(c),
            KeyCode::Enter => {
                let dir = Utf8PathBuf::from(expand_home(buf.trim()));
                m.new_dir = None;
                if dir.as_str().is_empty() {
                    return Ok(Flow::Continue);
                }
                if let Err(e) = std::fs::create_dir_all(&dir) {
                    m.status = format!("could not create {dir}: {e}");
                    return Ok(Flow::Continue);
                }
                run_child_inherit(terminal, &dir, &["init"])?;
                m.open_project(dir);
            }
            _ => {}
        }
        return Ok(Flow::Continue);
    }
    let n = m.visible().len();
    match (k.code, k.modifiers) {
        (KeyCode::Char('q'), _) | (KeyCode::Char('c'), KeyModifiers::CONTROL) => {
            return Ok(Flow::Quit);
        }
        (KeyCode::Char('?'), _) => m.show_keys = true,
        (KeyCode::Char(d @ '1'..='9'), _) => {
            m.pane = Pane::ALL[(d as u8 - b'1') as usize];
            m.reading = false;
        }
        (KeyCode::Char('0'), _) => {
            m.pane = Pane::Roadmap;
            m.reading = false;
        }
        (KeyCode::Char('t'), _) => {
            m.pane = Pane::Tickets;
            m.reading = false;
        }
        (KeyCode::Char('p'), _) => {
            m.pane = Pane::Projects;
            m.reading = false;
            m.load_projects();
        }
        (KeyCode::Char('n'), _) if m.pane == Pane::Projects => m.new_dir = Some(String::new()),
        (KeyCode::Char('r'), _) if m.pane == Pane::Projects => m.load_projects(),
        (KeyCode::Tab, _) => {
            let i = Pane::ALL.iter().position(|p| *p == m.pane).unwrap_or(0);
            m.pane = Pane::ALL[(i + 1) % Pane::ALL.len()];
            m.reading = false;
            if m.pane == Pane::Projects {
                m.load_projects();
            }
        }
        (KeyCode::BackTab, _) => {
            let i = Pane::ALL.iter().position(|p| *p == m.pane).unwrap_or(0);
            m.pane = Pane::ALL[(i + Pane::ALL.len() - 1) % Pane::ALL.len()];
            m.reading = false;
            if m.pane == Pane::Projects {
                m.load_projects();
            }
        }
        (KeyCode::Char('j'), _) | (KeyCode::Down, _) => {
            if m.reading {
                m.doc_index = (m.doc_index + 1) % m.docs.len().max(1);
            } else if n > 0 {
                m.select((m.selected() + 1).min(n - 1));
            }
        }
        (KeyCode::Char('k'), _) | (KeyCode::Up, _) => {
            if m.reading {
                m.doc_index = (m.doc_index + m.docs.len().max(1) - 1) % m.docs.len().max(1);
            } else {
                m.select(m.selected().saturating_sub(1));
            }
        }
        (KeyCode::Char('/'), _) => {
            m.filtering = true;
            m.filter.clear();
        }
        (KeyCode::Char('r'), _) => m.refresh(),
        (KeyCode::Char('['), _) | (KeyCode::Char(']'), _) if m.pane == Pane::Help => {
            m.reading = true;
            if k.code == KeyCode::Char(']') {
                m.doc_index = (m.doc_index + 1) % m.docs.len().max(1);
            } else {
                m.doc_index = (m.doc_index + m.docs.len().max(1) - 1) % m.docs.len().max(1);
            }
        }
        (KeyCode::Char('d'), _) if m.pane == Pane::Help => m.reading = !m.reading,
        (KeyCode::Char('c'), _) => {
            if let Some(repo) = m.repo.as_ref() {
                let text = crate::commit::message(repo)
                    .unwrap_or_else(|e| format!("could not compose: {e}"));
                m.popup = Some(("commit message (`war commit --write`)".to_owned(), text, 0));
            }
        }
        (KeyCode::Char(' '), _) if m.pane == Pane::Queue => {
            if let Some(i) = m.current_index()
                && !m.checked.remove(&i)
            {
                m.checked.insert(i);
            }
        }
        (KeyCode::Char('a'), _) if m.pane == Pane::Queue => {
            m.checked = (0..m.rows().len()).collect();
        }
        (KeyCode::Char('n'), _) if m.pane == Pane::Queue => m.checked.clear(),
        (KeyCode::Char('s'), _) if m.pane == Pane::Queue => {
            let targets: Vec<String> = m
                .rows()
                .iter()
                .enumerate()
                .filter(|(i, _)| m.checked.contains(i))
                .filter_map(|(_, r)| r.sign_target.clone())
                .collect();
            if targets.is_empty() {
                m.status = "nothing checked — space checks a row, a checks all".to_owned();
            } else if let [t] = targets.as_slice() {
                sign_in_child(terminal, m, t)?;
                m.checked.clear();
                m.refresh();
            } else {
                // More than one: one batch, one dialog (OW-WAR-0072).
                let list = format!("--batch={}", targets.join(","));
                run_child_inherit(terminal, &m.root, &["sign", &list, "--ssh-sign"])?;
                m.status = format!("returned from war sign {list}");
                m.checked.clear();
                m.refresh();
            }
        }
        (KeyCode::Char('v'), _) => {
            if let Some(t) = m.current().and_then(|r| r.sign_target.clone()) {
                let out = run_child_captured(&m.root, &["sign", &t, "--show"]);
                m.popup = Some((format!("war sign {t} --show"), out, 0));
            } else if let Some(r) = m.current() {
                m.popup = Some((
                    r.command.clone(),
                    r.detail.clone().unwrap_or_else(|| r.text.clone()),
                    0,
                ));
            }
        }
        (KeyCode::Char('x'), _) => {
            if let Some(argv) = m.current().and_then(|r| r.auto.clone()) {
                if argv.first().is_some_and(|a| a == "war") {
                    let args: Vec<&str> = argv.iter().skip(1).map(String::as_str).collect();
                    let out = run_child_captured(&m.root, &args);
                    m.popup = Some((argv.join(" "), out, 0));
                    m.refresh();
                } else {
                    m.popup = Some((
                        "not run from here".to_owned(),
                        format!(
                            "{}\n\nThis remedy is not a `war` command; run it in a shell.",
                            argv.join(" ")
                        ),
                        0,
                    ));
                }
            } else {
                m.status = "no auto remedy on this row".to_owned();
            }
        }
        (KeyCode::Enter, _) => match m.pane {
            Pane::Setup => {
                run_child_inherit(terminal, &m.root, &["init"])?;
                // The conversation may have created the repository.
                if m.repo.is_none() {
                    m.repo = Repository::discover(Some(m.root.clone())).ok();
                    if m.repo.is_some() {
                        m.docs = m.load_docs();
                    }
                }
                m.refresh();
            }
            Pane::Queue => {
                if let Some(t) = m.current().and_then(|r| r.sign_target.clone()) {
                    sign_in_child(terminal, m, &t)?;
                    m.refresh();
                }
            }
            Pane::Projects => match m.current_index() {
                Some(i) if m.projects.get(i).is_some_and(|r| !r.missing) => {
                    let root = Utf8PathBuf::from(&m.projects[i].root);
                    m.open_project(root);
                }
                Some(i) if i + 2 == m.rows().len() => m.new_dir = Some(String::new()),
                Some(i) if i + 1 == m.rows().len() => m.pane = Pane::Setup,
                _ => {
                    if let Some(r) = m.current() {
                        m.popup =
                            Some((r.command.clone(), r.detail.clone().unwrap_or_default(), 0));
                    }
                }
            },
            // One editor, two doors: the pane hands the terminal to
            // `war roadmap edit`, which ends in one signature.
            Pane::Roadmap => {
                run_child_inherit(terminal, &m.root, &["roadmap", "edit"])?;
                m.refresh();
            }
            _ => {
                if let Some(t) = m.current().and_then(|r| r.sign_target.clone()) {
                    sign_in_child(terminal, m, &t)?;
                    m.refresh();
                } else if let Some(r) = m.current() {
                    m.popup = Some((
                        r.command.clone(),
                        r.detail.clone().unwrap_or_else(|| r.command.clone()),
                        0,
                    ));
                }
            }
        },
        _ => {}
    }
    Ok(Flow::Continue)
}

/// `war sign <target> --ssh-sign` in a child that owns the terminal: the
/// app steps out of the alternate screen and raw mode, waits, steps back.
fn sign_in_child(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    m: &mut Model,
    target: &str,
) -> Result<(), RepoError> {
    run_child_inherit(terminal, &m.root, &["sign", target, "--ssh-sign"])?;
    m.status = format!("returned from war sign {target}");
    Ok(())
}

fn run_child_inherit(
    terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
    root: &Utf8Path,
    args: &[&str],
) -> Result<(), RepoError> {
    term::leave_quietly();
    let exe = std::env::current_exe().map_err(io("could not find this executable"))?;
    let mut stdout = std::io::stdout();
    let _ = writeln!(stdout, "$ war {}", args.join(" "));
    let status = std::process::Command::new(exe)
        .arg("--root")
        .arg(root.as_str())
        .args(args)
        .current_dir(root)
        .status();
    let _ = writeln!(
        stdout,
        "\n[war {} exited {}] — press Enter to return",
        args.join(" "),
        status.as_ref().map_or(-1, |s| s.code().unwrap_or(-1))
    );
    let mut line = String::new();
    let _ = std::io::stdin().read_line(&mut line);
    let _ = term::Guard::enter().map(std::mem::forget);
    terminal
        .clear()
        .map_err(io("could not clear the terminal"))?;
    Ok(())
}

/// `~/x` → `$HOME/x`: a directory typed at the prompt reads as a shell would.
fn expand_home(s: &str) -> String {
    match (s.strip_prefix("~/"), std::env::var("HOME")) {
        (Some(rest), Ok(home)) => format!("{home}/{rest}"),
        _ if s == "~" => std::env::var("HOME").unwrap_or_else(|_| s.to_owned()),
        _ => s.to_owned(),
    }
}

/// A child whose output the app shows in a popup: `--show`, an auto remedy.
fn run_child_captured(root: &Utf8Path, args: &[&str]) -> String {
    let Ok(exe) = std::env::current_exe() else {
        return "could not find this executable".to_owned();
    };
    match std::process::Command::new(exe)
        .arg("--root")
        .arg(root.as_str())
        .args(args)
        .current_dir(root)
        .output()
    {
        Ok(out) => {
            let mut s = String::from_utf8_lossy(&out.stdout).into_owned();
            let err = String::from_utf8_lossy(&out.stderr);
            if !err.trim().is_empty() {
                s.push_str("\n--- stderr ---\n");
                s.push_str(&err);
            }
            s.push_str(&format!("\n[exit {}]", out.status.code().unwrap_or(-1)));
            s
        }
        Err(e) => format!("could not run war {}: {e}", args.join(" ")),
    }
}

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------

fn draw(f: &mut ratatui::Frame, m: &Model) {
    let area = f.area();
    let [tabs_area, body, cmd_line, status_line] = Layout::vertical([
        Constraint::Length(3),
        Constraint::Min(1),
        Constraint::Length(1),
        Constraint::Length(1),
    ])
    .areas(area);

    let titles: Vec<Line> = Pane::ALL.iter().map(|p| Line::from(p.title())).collect();
    let selected = Pane::ALL.iter().position(|p| *p == m.pane).unwrap_or(0);
    f.render_widget(
        Tabs::new(titles)
            .select(selected)
            .highlight_style(
                Style::default()
                    .fg(Color::Yellow)
                    .add_modifier(Modifier::BOLD),
            )
            .block(Block::default().borders(Borders::ALL).title(" war ")),
        tabs_area,
    );

    if m.pane == Pane::Help && m.reading {
        draw_doc(f, m, body);
    } else {
        draw_list(f, m, body);
    }

    let command = m.current().map_or_else(String::new, |r| r.command.clone());
    f.render_widget(
        Paragraph::new(Line::from(vec![
            Span::styled("  $ ", Style::default().fg(Color::DarkGray)),
            Span::raw(command),
        ])),
        cmd_line,
    );
    let status = if let Some(buf) = &m.new_dir {
        format!("  new project directory (Enter runs war init there, Esc cancels): {buf}_")
    } else if m.filtering {
        format!("  / {}_", m.filter)
    } else if !m.filter.is_empty() {
        format!("  {}   filter: {}   (Esc clears)", m.status, m.filter)
    } else {
        format!("  {}   ? keys · q quit", m.status)
    };
    f.render_widget(
        Paragraph::new(status).style(Style::default().fg(Color::Black).bg(Color::Gray)),
        status_line,
    );

    if let Some((title, text, scroll)) = &m.popup {
        let area = centered(area, 90, 85);
        f.render_widget(Clear, area);
        f.render_widget(
            Paragraph::new(md::render(text))
                .block(
                    Block::default()
                        .borders(Borders::ALL)
                        .title(format!(" {title}  (j/k scroll · Esc) ")),
                )
                .wrap(Wrap { trim: false })
                .scroll((*scroll, 0)),
            area,
        );
    }
    if m.show_keys {
        let area = centered(area, 70, 70);
        f.render_widget(Clear, area);
        f.render_widget(
            Paragraph::new(KEYS)
                .block(
                    Block::default()
                        .borders(Borders::ALL)
                        .title(" keys (any key closes) "),
                )
                .wrap(Wrap { trim: false }),
            area,
        );
    }
}

fn draw_list(f: &mut ratatui::Frame, m: &Model, body: Rect) {
    let rows = m.visible();
    let items: Vec<ListItem> = rows
        .iter()
        .map(|(i, r)| {
            let mark = if m.pane == Pane::Queue {
                if m.checked.contains(i) {
                    "[x] "
                } else {
                    "[ ] "
                }
            } else {
                ""
            };
            let style = if r.text.starts_with("ERROR") || r.text.starts_with("UNREADABLE") {
                Style::default().fg(Color::Red)
            } else if r.text.starts_with("WARN") || r.text.starts_with("BLOCKING") {
                Style::default().fg(Color::Yellow)
            } else if r.text.starts_with("HUMAN") {
                Style::default().add_modifier(Modifier::BOLD)
            } else {
                Style::default()
            };
            ListItem::new(Line::from(vec![
                Span::raw(mark),
                Span::styled(r.text.clone(), style),
            ]))
        })
        .collect();
    let title = match m.pane {
        Pane::Setup => format!(" Setup — {} ", m.setup.step.title()),
        Pane::Help => " Help — what next (d: documents, [ ]: step through them) ".to_owned(),
        Pane::Queue => format!(
            " Queue — {} act(s); space checks, s signs checked, Enter signs row, v shows request ",
            m.pending_count
        ),
        Pane::Questions => {
            " Questions — blocking first; Enter shows, the command answers ".to_owned()
        }
        Pane::Frontier => " Frontier — stages by state; the command starts one ".to_owned(),
        Pane::Corpus => " Corpus — rungs; Enter shows the thirteen ".to_owned(),
        Pane::Obligations => " Obligations — disposition, verifier, admissibility ".to_owned(),
        Pane::Evidence => " Evidence — gate runs by class; x records again ".to_owned(),
        Pane::Journal => " Journal — newest first; / filters by day or kind ".to_owned(),
        Pane::Roadmap => {
            " Roadmap — phases in order; Enter edits by keystroke and signs once ".to_owned()
        }
        Pane::Projects => {
            " Projects — every repository you use; Enter opens, n starts a new one ".to_owned()
        }
        Pane::Tickets => {
            " Tickets — state and progress, remaining items; Enter shows checklist and notes "
                .to_owned()
        }
    };
    let mut state = ListState::default();
    if !rows.is_empty() {
        state.select(Some(m.selected().min(rows.len() - 1)));
    }
    let list = List::new(items)
        .block(Block::default().borders(Borders::ALL).title(title))
        .highlight_style(Style::default().bg(Color::Blue).fg(Color::White))
        .highlight_symbol("▶ ");
    f.render_stateful_widget(list, body, &mut state);
    if rows.is_empty() {
        let inner = Rect {
            x: body.x + 2,
            y: body.y + 1,
            width: body.width.saturating_sub(4),
            height: 1,
        };
        f.render_widget(
            Paragraph::new(if m.filter.is_empty() {
                "nothing here — not established, not blank"
            } else {
                "nothing matches the filter"
            })
            .style(Style::default().fg(Color::DarkGray)),
            inner,
        );
    }
}

fn draw_doc(f: &mut ratatui::Frame, m: &Model, body: Rect) {
    let Some(doc) = m.docs.get(m.doc_index) else {
        return;
    };
    f.render_widget(
        Paragraph::new(md::render(&doc.text))
            .block(Block::default().borders(Borders::ALL).title(format!(
                " {} ({}/{})  [ ] other documents · d back to what-next ",
                doc.name,
                m.doc_index + 1,
                m.docs.len()
            )))
            .wrap(Wrap { trim: false }),
        body,
    );
}

fn centered(area: Rect, pct_w: u16, pct_h: u16) -> Rect {
    let w = area.width * pct_w / 100;
    let h = area.height * pct_h / 100;
    Rect {
        x: area.x + (area.width - w) / 2,
        y: area.y + (area.height - h) / 2,
        width: w,
        height: h,
    }
}

