        #[arg(long, requires = "lan", conflicts_with_all = ["cert", "key"])]
        self_signed: bool,
        /// Seconds the host's human has to answer a pairing. Hidden; the battery's.
        #[arg(long, hide = true)]
        pair_answer_secs: Option<u64>,
        /// Seconds a pairing code lives. Hidden; the battery's.
        #[arg(long, hide = true)]
