        /// It must always fail; a build where this succeeds is the defect.
        #[arg(long)]
        attempt_promotion: bool,
    },

    /// Experimental preservation transport. Imported records grant no authority.
    Archive {
        #[command(subcommand)]
        cmd: preservation::Command,
    },

