        #[arg(long)]
        ssh_sign: bool,
        /// Verify a recorded response's .sig sidecar and stop. Writes nothing.
        #[arg(long)]
        verify: bool,
        /// For a correction (`<alias>/<D-id>`): behaviour-change | added-refusal.
        #[arg(long)]
        kind: Option<String>,
        /// One signature over many acts (OW-WAR-0072). Alone: every pending
